package com.hmall.service.impl;

import cn.hutool.jwt.JWT;
import com.hmall.config.JwtProperties;
import com.hmall.domain.dto.LoginFormDTO;
import com.hmall.domain.po.User;
import com.hmall.domain.vo.UserLoginVO;
import com.hmall.enums.UserStatus;
import com.hmall.mapper.UserMapper;
import com.hmall.utils.JwtTool;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.util.ReflectionTestUtils;

import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.time.Duration;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class UserServiceLoginTokenTest {

    @Test
    void loginTokenContainsPersistedRoleClaim() throws Exception {
        User user = new User()
                .setId(1L)
                .setUsername("admin")
                .setPassword("encoded")
                .setStatus(UserStatus.NORMAL)
                .setBalance(1000)
                .setRole("ADMIN");

        UserLoginVO login = login(user);

        assertThat(JWT.of(login.getToken()).getPayload("user")).hasToString("1");
        assertThat(JWT.of(login.getToken()).getPayload("role")).isEqualTo("ADMIN");
    }

    @ParameterizedTest
    @NullAndEmptySource
    void loginTokenFallsBackToUserWhenPersistedRoleIsMissing(String role) throws Exception {
        User user = new User()
                .setId(2L)
                .setUsername("customer")
                .setPassword("encoded")
                .setStatus(UserStatus.NORMAL)
                .setBalance(1000)
                .setRole(role);

        UserLoginVO login = login(user);

        assertThat(JWT.of(login.getToken()).getPayload("role")).isEqualTo("USER");
    }

    private UserLoginVO login(User user) throws Exception {
        UserMapper mapper = mock(UserMapper.class);
        when(mapper.selectOne(any())).thenReturn(user);
        PasswordEncoder passwordEncoder = mock(PasswordEncoder.class);
        when(passwordEncoder.matches("secret", "encoded")).thenReturn(true);

        KeyPairGenerator generator = KeyPairGenerator.getInstance("RSA");
        generator.initialize(2048);
        KeyPair keyPair = generator.generateKeyPair();
        JwtProperties properties = new JwtProperties();
        properties.setTokenTTL(Duration.ofMinutes(5));
        UserServiceImpl service = new UserServiceImpl(passwordEncoder, new JwtTool(keyPair), properties);
        ReflectionTestUtils.setField(service, "baseMapper", mapper);

        LoginFormDTO form = new LoginFormDTO();
        form.setUsername(user.getUsername());
        form.setPassword("secret");
        return service.login(form);
    }
}

param(
    [string] $ConfirmLocalDemoData
)

$ErrorActionPreference = 'Stop'

if ($ConfirmLocalDemoData -cne 'YES') {
    throw '必须显式传入 -ConfirmLocalDemoData YES，才允许初始化本地演示数据。'
}

$blockedOverrides = [System.Collections.Generic.List[string]]::new()
Get-ChildItem Env: | ForEach-Object {
    $normalizedName = $_.Name.ToUpperInvariant()
    $isBlocked = $normalizedName.StartsWith('SPRING_DATASOURCE_') -or
        $normalizedName.StartsWith('SPRING_FLYWAY_') -or
        $normalizedName.StartsWith('SPRING_CONFIG_') -or
        $normalizedName -in @(
            'SPRING_APPLICATION_JSON', 'SPRING_PROFILES_ACTIVE',
            'MAVEN_ARGS', 'MAVEN_OPTS', 'MAVEN_PROJECTBASEDIR',
            'JAVA_TOOL_OPTIONS', '_JAVA_OPTIONS', 'JDK_JAVA_OPTIONS'
        )
    if ($isBlocked -and -not [string]::IsNullOrWhiteSpace($_.Value)) {
        $blockedOverrides.Add($_.Name)
    }
}
if ($blockedOverrides.Count -gt 0) {
    throw "检测到可能覆盖数据源的环境变量，拒绝启动 Maven：$($blockedOverrides -join ', ')"
}

$moduleRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..\..')).Path
$repositoryRoot = (Resolve-Path -LiteralPath (Join-Path $moduleRoot '..')).Path
foreach ($mavenRoot in @($repositoryRoot, $moduleRoot)) {
    $mavenConfigurationDirectory = Join-Path $mavenRoot '.mvn'
    foreach ($configurationName in @('maven.config', 'jvm.config')) {
        $configurationPath = Join-Path $mavenConfigurationDirectory $configurationName
        if ((Test-Path -LiteralPath $configurationPath -PathType Leaf) -and
            -not [string]::IsNullOrWhiteSpace((Get-Content -Raw -LiteralPath $configurationPath))) {
            throw "检测到非空 Maven 项目配置 .mvn/$configurationName，拒绝启动 Maven。"
        }
    }
}

$envFile = Join-Path $repositoryRoot '.env'
if (-not (Test-Path -LiteralPath $envFile -PathType Leaf)) {
    throw '缺少仓库根目录 .env，无法确认本地数据库目标。'
}

$settings = @{}
Get-Content -Encoding UTF8 -LiteralPath $envFile |
    Where-Object { $_ -match '^[A-Z0-9_]+=' } |
    ForEach-Object {
        $key, $value = $_ -split '=', 2
        $settings[$key] = $value.Trim()
    }

# 当前进程环境变量优先，便于安全测试验证远程主机一定会被拒绝。
$mysqlHost = if (Test-Path Env:MYSQL_HOST) { $env:MYSQL_HOST } elseif ($settings['MYSQL_HOST']) { $settings['MYSQL_HOST'] } else { 'localhost' }
$mysqlDatabase = if (Test-Path Env:MYSQL_DATABASE) { $env:MYSQL_DATABASE } elseif ($settings['MYSQL_DATABASE']) { $settings['MYSQL_DATABASE'] } else { 'luckyhub' }
$mysqlPort = if (Test-Path Env:MYSQL_PORT) { $env:MYSQL_PORT } else { $settings['MYSQL_PORT'] }

$allowedLocalHosts = @('localhost', '127.0.0.1', '::1')
if ([string]::IsNullOrWhiteSpace($mysqlHost) -or $allowedLocalHosts -notcontains $mysqlHost.Trim().ToLowerInvariant()) {
    throw "检测到非本机 MySQL 主机 '$mysqlHost'，拒绝写入演示数据。"
}
if ([string]::IsNullOrWhiteSpace($mysqlDatabase) -or
    $mysqlDatabase -notmatch '^luckyhub(?:_[a-zA-Z0-9_]+)?$') {
    throw "数据库名称 '$mysqlDatabase' 不在允许的 LuckyHub 本地命名范围内，拒绝写入。"
}
if ($mysqlPort -notmatch '^[0-9]{1,5}$' -or [int]$mysqlPort -lt 1 -or [int]$mysqlPort -gt 65535) {
    throw "MySQL 端口 '$mysqlPort' 不合法，拒绝写入。"
}

$jdbcHost = if ($mysqlHost.Trim() -eq '::1') { '[::1]' } else { $mysqlHost.Trim().ToLowerInvariant() }
$verifiedJdbcUrl = "jdbc:mysql://${jdbcHost}:$mysqlPort/$mysqlDatabase"
$env:SPRING_DATASOURCE_URL = $verifiedJdbcUrl
$env:SPRING_FLYWAY_ENABLED = 'false'

$mavenWrapper = Join-Path $moduleRoot 'scripts\Invoke-Maven.ps1'
Write-Host "已确认本地数据库：$mysqlHost / $mysqlDatabase"
Write-Host '正在执行幂等演示数据初始化与安全快照测试……'

Push-Location -LiteralPath $moduleRoot
try {
    & pwsh -NoProfile -ExecutionPolicy Bypass -File $mavenWrapper `
        '-Dfrontend.demo.seed=true' `
        "-Dfrontend.demo.expected-database=$mysqlDatabase" `
        '-Dspring.flyway.enabled=false' `
        '-Dtest=FrontendDemoDataSeederTests,FrontendDemoDataSafetyTests' `
        test

    if ($LASTEXITCODE -ne 0) {
        throw "演示数据初始化或安全验证失败，Maven 退出码：$LASTEXITCODE"
    }
}
finally {
    Pop-Location
}

Write-Host '演示数据初始化完成；重复执行不会增加重复的 DEMO- 业务数据。'

param(
    [string] $SchemaName = ("luckyhub_phase4_verify_" + [Guid]::NewGuid().ToString("N"))
)

$ErrorActionPreference = 'Stop'

if ($SchemaName -notmatch '^luckyhub_phase4_verify_[a-zA-Z0-9_]+$') {
    throw '临时数据库名称不安全。'
}

$settings = @{}
Get-Content -Encoding UTF8 -LiteralPath (Join-Path $PSScriptRoot '..\.env') |
    Where-Object { $_ -match '^[A-Z0-9_]+=' } |
    ForEach-Object {
        $key, $value = $_ -split '=', 2
        $settings[$key] = $value.Trim()
    }

$rootPassword = $settings['MYSQL_ROOT_PASSWORD']
$applicationUser = $settings['MYSQL_USER']
if ([string]::IsNullOrWhiteSpace($rootPassword) -or $applicationUser -notmatch '^[a-zA-Z0-9_]+$') {
    throw '缺少安全的 MYSQL_ROOT_PASSWORD 或 MYSQL_USER。'
}

$previousDatabase = $env:MYSQL_DATABASE
$sqlUser = "'$applicationUser'@'%'"
$schemaCreated = $false

try {
    & docker exec -e "MYSQL_PWD=$rootPassword" luckyhub-mysql mysql -uroot -Nse `
        "CREATE DATABASE ``$SchemaName`` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;"
    if ($LASTEXITCODE -ne 0) { throw '创建临时数据库失败。' }
    $schemaCreated = $true

    & docker exec -e "MYSQL_PWD=$rootPassword" luckyhub-mysql mysql -uroot -Nse `
        "GRANT ALL PRIVILEGES ON ``$SchemaName``.* TO $sqlUser; FLUSH PRIVILEGES;"
    if ($LASTEXITCODE -ne 0) { throw '临时数据库授权失败。' }

    $env:MYSQL_DATABASE = $SchemaName
    & pwsh -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'Invoke-Maven.ps1') `
        '-Dtest=FulfillmentSchemaContractTests,DatabaseSchemaMigrationTests' test
    if ($LASTEXITCODE -ne 0) { throw 'V1 到 V15 空库迁移验证失败。' }

    $summary = & docker exec -e "MYSQL_PWD=$rootPassword" luckyhub-mysql mysql -uroot -Nse `
        "SELECT CONCAT(MAX(CAST(version AS UNSIGNED)), '|', (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='$SchemaName' AND table_type='BASE TABLE' AND table_name<>'flyway_schema_history')) FROM ``$SchemaName``.flyway_schema_history WHERE success=1;"
    if ($LASTEXITCODE -ne 0 -or $summary -ne '15|39') {
        throw "临时数据库验收摘要不符：$summary"
    }
    Write-Host "Fresh migration verified: V15, 39 business tables."
}
finally {
    $env:MYSQL_DATABASE = $previousDatabase
    if ($schemaCreated) {
        & docker exec -e "MYSQL_PWD=$rootPassword" luckyhub-mysql mysql -uroot -Nse `
            "REVOKE ALL PRIVILEGES ON ``$SchemaName``.* FROM $sqlUser; DROP DATABASE IF EXISTS ``$SchemaName``; FLUSH PRIVILEGES;" 2>$null
        if ($LASTEXITCODE -ne 0) {
            throw "临时授权或数据库清理失败：$SchemaName"
        }
        Write-Host "Temporary grant revoked and schema dropped: $SchemaName"
    }
}

