package com.dongqh.luckyhub.config.lottery;

import com.dongqh.luckyhub.messaging.lottery.rabbit.LotteryRabbitTopology;
import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.Declarables;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
import org.springframework.amqp.core.TopicExchange;
import org.springframework.amqp.support.converter.JacksonJsonMessageConverter;
import org.springframework.amqp.support.converter.MessageConverter;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(MessagingProperties.class)
public class LotteryMessagingConfiguration {

    @Bean
    @ConditionalOnProperty(
            prefix = "luckyhub.messaging",
            name = "enabled",
            havingValue = "true",
            matchIfMissing = true)
    public MessageConverter rabbitMessageConverter() {
        return new JacksonJsonMessageConverter();
    }

    @Bean
    @ConditionalOnProperty(
            prefix = "luckyhub.messaging",
            name = "enabled",
            havingValue = "true",
            matchIfMissing = true)
    public Declarables lotteryRabbitDeclarables() {
        TopicExchange eventExchange = new TopicExchange(
                LotteryRabbitTopology.EVENT_EXCHANGE, true, false);
        TopicExchange deadLetterExchange = new TopicExchange(
                LotteryRabbitTopology.DEAD_LETTER_EXCHANGE, true, false);
        Queue eventQueue = QueueBuilder.durable(LotteryRabbitTopology.EVENT_QUEUE)
                .deadLetterExchange(LotteryRabbitTopology.DEAD_LETTER_EXCHANGE)
                .build();
        Queue deadLetterQueue = QueueBuilder.durable(LotteryRabbitTopology.DEAD_LETTER_QUEUE)
                .build();

        return new Declarables(
                eventExchange,
                deadLetterExchange,
                eventQueue,
                deadLetterQueue,
                BindingBuilder.bind(eventQueue).to(eventExchange)
                        .with(LotteryRabbitTopology.DRAW_CONFIRMED_KEY),
                BindingBuilder.bind(eventQueue).to(eventExchange)
                        .with(LotteryRabbitTopology.DRAW_RELEASE_REQUESTED_KEY),
                BindingBuilder.bind(eventQueue).to(eventExchange)
                        .with(LotteryRabbitTopology.PRIZE_FULFILLMENT_REQUESTED_KEY),
                BindingBuilder.bind(deadLetterQueue).to(deadLetterExchange).with("#"));
    }
}

package com.dongqh.luckyhub.config.lottery;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.time.Duration;
import java.time.ZoneId;

@ConfigurationProperties(prefix = "luckyhub.lottery")
public record LotteryProperties(
        ZoneId zoneId,
        Duration lockWait,
        Duration processingTimeout,
        Duration reconcileInterval,
        Duration reconcileInitialDelay,
        int reconcileBatchSize,
        Duration outboxInterval,
        int outboxBatchSize
) {
    public LotteryProperties {
        if (zoneId == null) {
            throw new IllegalArgumentException("zoneId must not be null");
        }
        requirePositive(lockWait, "lockWait");
        requirePositive(processingTimeout, "processingTimeout");
        requirePositive(reconcileInterval, "reconcileInterval");
        if (reconcileInitialDelay == null || reconcileInitialDelay.isNegative()) {
            throw new IllegalArgumentException("reconcileInitialDelay must not be negative");
        }
        if (reconcileBatchSize <= 0) {
            throw new IllegalArgumentException("reconcileBatchSize must be positive");
        }
        requirePositive(outboxInterval, "outboxInterval");
        if (outboxBatchSize <= 0) {
            throw new IllegalArgumentException("outboxBatchSize must be positive");
        }
    }

    private static void requirePositive(Duration value, String name) {
        if (value == null || value.isZero() || value.isNegative()) {
            throw new IllegalArgumentException(name + " must be positive");
        }
    }
}

package com.dongqh.luckyhub.config.lottery;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.time.Duration;

@ConfigurationProperties(prefix = "luckyhub.messaging")
public record MessagingProperties(
        boolean enabled,
        String logicalConsumerName,
        Duration publisherConfirmTimeout,
        Duration outboxLease
) {
    public MessagingProperties {
        if (!hasText(logicalConsumerName)) {
            throw new IllegalArgumentException("logicalConsumerName must not be blank");
        }
        requirePositive(publisherConfirmTimeout, "publisherConfirmTimeout");
        requirePositive(outboxLease, "outboxLease");
    }

    private static boolean hasText(String value) {
        return value != null && !value.isBlank();
    }

    private static void requirePositive(Duration value, String name) {
        if (value == null || value.isZero() || value.isNegative()) {
            throw new IllegalArgumentException(name + " must be positive");
        }
    }
}

