 private static int required(Integer v){if(v==null)throw new IllegalArgumentException();return v;}private static long required(Long v){if(v==null)throw new IllegalArgumentException();return v;}
 public record Payload(String couponTemplateCode,Integer quantity,Long points,String reason,String membershipCode,Integer durationDays,Long shippingOrderId,String skuCode,String receiverMasked,String phoneMasked,String regionMasked){}
}

