package com.dongqh.luckyhub.domain.image.prize;

import com.dongqh.luckyhub.config.prize.OssProperties;
import com.dongqh.luckyhub.domain.storage.prize.ObjectStorageGateway;
import com.dongqh.luckyhub.domain.vo.prize.ImageUploadView;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.time.Clock;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.UUID;
import java.util.function.Supplier;

@Service
public class PrizeImageService {

    private static final DateTimeFormatter PATH_DATE = DateTimeFormatter.ofPattern("yyyy/MM");

    private final PrizeImageValidator validator;
    private final ObjectStorageGateway gateway;
    private final OssProperties properties;
    private final Clock clock;
    private final Supplier<UUID> uuidSupplier;

    @Autowired
    public PrizeImageService(
            PrizeImageValidator validator,
            ObjectStorageGateway gateway,
            OssProperties properties
    ) {
        this(validator, gateway, properties, Clock.systemUTC(), UUID::randomUUID);
    }

    PrizeImageService(
            PrizeImageValidator validator,
            ObjectStorageGateway gateway,
            OssProperties properties,
            Clock clock,
            Supplier<UUID> uuidSupplier
    ) {
        this.validator = validator;
        this.gateway = gateway;
        this.properties = properties;
        this.clock = clock;
        this.uuidSupplier = uuidSupplier;
    }

    public ImageUploadView upload(MultipartFile file) {
        ValidatedImage image = validator.validate(file);
        String objectKey = "prizes/%s/%s.%s".formatted(
                LocalDate.now(clock).format(PATH_DATE),
                uuidSupplier.get(),
                image.extension()
        );
        gateway.put(objectKey, image.content(), image.contentType());
        String url = properties.normalizedPublicBaseUrl() + "/" + objectKey;
        return new ImageUploadView(url, objectKey);
    }
}

package com.dongqh.luckyhub.domain.image.prize;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.enums.prize.PrizeErrorCode;
import org.springframework.stereotype.Component;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.util.Arrays;

@Component
public class PrizeImageValidator {

    static final long MAX_IMAGE_BYTES = 5L * 1024 * 1024;

    public ValidatedImage validate(MultipartFile file) {
        if (file == null || file.isEmpty()) {
            throw new BusinessException(PrizeErrorCode.IMAGE_EMPTY);
        }
        if (file.getSize() > MAX_IMAGE_BYTES) {
            throw new BusinessException(PrizeErrorCode.IMAGE_TOO_LARGE);
        }
        byte[] content;
        try {
            content = file.getBytes();
        } catch (IOException exception) {
            throw new BusinessException(PrizeErrorCode.OSS_UPLOAD_FAILED);
        }
        if (content.length > MAX_IMAGE_BYTES) {
            throw new BusinessException(PrizeErrorCode.IMAGE_TOO_LARGE);
        }
        ImageFormat format = detect(content);
        if (format == null || !format.contentType.equals(file.getContentType())) {
            throw new BusinessException(PrizeErrorCode.IMAGE_TYPE_UNSUPPORTED);
        }
        return new ValidatedImage(content, format.contentType, format.extension);
    }

    private ImageFormat detect(byte[] content) {
        if (startsWith(content, new byte[]{(byte) 0xFF, (byte) 0xD8, (byte) 0xFF})) {
            return ImageFormat.JPEG;
        }
        if (startsWith(content, new byte[]{
                (byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A
        })) {
            return ImageFormat.PNG;
        }
        if (content.length >= 12
                && Arrays.equals(Arrays.copyOfRange(content, 0, 4), new byte[]{'R', 'I', 'F', 'F'})
                && Arrays.equals(Arrays.copyOfRange(content, 8, 12), new byte[]{'W', 'E', 'B', 'P'})) {
            return ImageFormat.WEBP;
        }
        return null;
    }

    private boolean startsWith(byte[] content, byte[] signature) {
        return content.length >= signature.length
                && Arrays.equals(Arrays.copyOf(content, signature.length), signature);
    }

    private enum ImageFormat {
        JPEG("image/jpeg", "jpg"),
        PNG("image/png", "png"),
        WEBP("image/webp", "webp");

        private final String contentType;
        private final String extension;

        ImageFormat(String contentType, String extension) {
            this.contentType = contentType;
            this.extension = extension;
        }
    }
}

