package com.dongqh.luckyhub.service.lottery.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.domain.po.activity.MarketingActivity;
import com.dongqh.luckyhub.domain.po.activity.MarketingActivityPrize;
import com.dongqh.luckyhub.enums.activity.ActivityStatus;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityMapper;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityPrizeMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.config.lottery.LotteryProperties;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.domain.model.lottery.DrawPrizeSnapshot;
import com.dongqh.luckyhub.service.lottery.DrawEligibilityService;
import com.dongqh.luckyhub.domain.po.prize.MarketingPrize;
import com.dongqh.luckyhub.mapper.prize.MarketingPrizeMapper;
import com.dongqh.luckyhub.domain.model.reward.RewardSnapshot;
import com.dongqh.luckyhub.service.reward.RewardSnapshotService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
public class DrawEligibilityServiceImpl implements DrawEligibilityService {
    private final MarketingActivityMapper activityMapper;
    private final MarketingActivityPrizeMapper relationMapper;
    private final MarketingPrizeMapper prizeMapper;
    private final RewardSnapshotService rewardSnapshots;
    private final Clock clock;

    @Autowired
    public DrawEligibilityServiceImpl(MarketingActivityMapper activityMapper,
                                      MarketingActivityPrizeMapper relationMapper,
                                      MarketingPrizeMapper prizeMapper,
                                      RewardSnapshotService rewardSnapshots,
                                      LotteryProperties properties) {
        this(activityMapper, relationMapper, prizeMapper, rewardSnapshots,
                Clock.system(properties.zoneId()));
    }

    DrawEligibilityServiceImpl(MarketingActivityMapper activityMapper,
                               MarketingActivityPrizeMapper relationMapper,
                               MarketingPrizeMapper prizeMapper,
                               RewardSnapshotService rewardSnapshots, Clock clock) {
        this.activityMapper = activityMapper;
        this.relationMapper = relationMapper;
        this.prizeMapper = prizeMapper;
        this.rewardSnapshots = rewardSnapshots;
        this.clock = clock;
    }

    @Override
    public EligibilitySnapshot load(long activityId) {
        MarketingActivity activity = activityMapper.selectById(activityId);
        if (activity == null) throw new BusinessException(LotteryErrorCode.ACTIVITY_NOT_FOUND);
        // MySQL DATETIME(3) stores milliseconds. Normalize before the synchronous response so
        // an idempotent retry read from MySQL is byte-for-byte equivalent to the first response.
        LocalDateTime now = LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS);
        if (activity.getStatus() != ActivityStatus.RUNNING
                || activity.getStartTime() == null || activity.getEndTime() == null
                || now.isBefore(activity.getStartTime()) || !now.isBefore(activity.getEndTime())) {
            throw new BusinessException(LotteryErrorCode.ACTIVITY_NOT_AVAILABLE);
        }
        List<MarketingActivityPrize> relations = relationMapper.selectList(
                new LambdaQueryWrapper<MarketingActivityPrize>()
                        .eq(MarketingActivityPrize::getActivityId, activityId)
                        .orderByAsc(MarketingActivityPrize::getSortOrder)
                        .orderByAsc(MarketingActivityPrize::getId));
        List<Long> prizeIds = relations.stream().map(MarketingActivityPrize::getPrizeId).distinct().toList();
        Map<Long, MarketingPrize> prizes = prizeIds.isEmpty() ? Map.of()
                : prizeMapper.selectByIds(prizeIds).stream()
                .collect(Collectors.toMap(MarketingPrize::getId, Function.identity()));
        Map<Long, RewardSnapshot> resolvedRewards = rewardSnapshots.resolveForPrizes(
                prizeIds.stream().map(prizes::get).filter(Objects::nonNull).toList());
        List<DrawPrizeSnapshot> snapshots = relations.stream().map(relation -> {
            MarketingPrize prize = prizes.get(relation.getPrizeId());
            if (prize == null) throw new BusinessException(LotteryErrorCode.DRAW_WEIGHT_INVALID);
            return new DrawPrizeSnapshot(relation.getId(), prize.getId(), prize.getPrizeName(),
                    prize.getPrizeType(), prize.getImageUrl(), relation.getWeight(),
                    relation.getRemainingStock(), Integer.valueOf(1).equals(prize.getStatus()),
                    resolvedRewards.get(prize.getId()));
        }).toList();
        int noWinWeight = activity.getNoWinWeight() == null ? 0 : activity.getNoWinWeight();
        if (noWinWeight < 0 || (snapshots.isEmpty() && noWinWeight == 0)) {
            throw new BusinessException(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        return new EligibilitySnapshot(activityId, noWinWeight, snapshots, now);
    }
}

package com.dongqh.luckyhub.service.lottery.impl;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawOrder;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawOrderMapper;
import com.dongqh.luckyhub.domain.model.lottery.NewDrawOrder;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventEnvelope;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventType;
import com.dongqh.luckyhub.messaging.lottery.event.DrawReleaseRequestedEvent;
import com.dongqh.luckyhub.service.lottery.DrawOrderLifecycleService;
import com.dongqh.luckyhub.service.lottery.OutboxService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Objects;
import tools.jackson.databind.ObjectMapper;

@Service
public class DrawOrderLifecycleServiceImpl implements DrawOrderLifecycleService {

    private static final int MAX_REASON_LENGTH = 500;
    private static final String DEFAULT_SAFE_REASON = "DRAW_TRANSACTION_FAILED";

    private final LotteryDrawOrderMapper orderMapper;
    private final OutboxService outboxService;
    private final ObjectMapper objectMapper;

    public DrawOrderLifecycleServiceImpl(LotteryDrawOrderMapper orderMapper,
                                         OutboxService outboxService,
                                         ObjectMapper objectMapper) {
        this.orderMapper = orderMapper;
        this.outboxService = outboxService;
        this.objectMapper = objectMapper;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public LotteryDrawOrder createProcessing(NewDrawOrder command) {
        Objects.requireNonNull(command, "command must not be null");
        LotteryDrawOrder existing = orderMapper.selectByRequestId(command.requestId());
        if (existing != null) {
            validateIdentity(existing, command);
            return existing;
        }

        LotteryDrawOrder order = new LotteryDrawOrder();
        order.setRequestId(command.requestId());
        order.setUserId(command.userId());
        order.setActivityId(command.activityId());
        order.setDrawCount(command.drawCount());
        order.setDrawDate(command.drawDate());
        order.setStatus(DrawOrderStatus.PROCESSING);
        orderMapper.insertProcessingIfAbsent(order);

        // A locking read is a current read under InnoDB REPEATABLE READ. The first
        // plain SELECT may have established a snapshot before a concurrent creator
        // committed, so another plain SELECT could incorrectly keep returning null.
        LotteryDrawOrder persisted = orderMapper.selectByRequestIdForUpdate(command.requestId());
        validateIdentity(persisted, command);
        return persisted;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void markFailed(long orderId, String safeReason) {
        if (orderId <= 0) {
            throw new IllegalArgumentException("orderId must be positive");
        }
        orderMapper.markFailedIfProcessing(orderId, normalizeReason(safeReason));
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void markFailedAndRequestRelease(LotteryDrawOrder order, String safeReason,
                                            LocalDateTime occurredAt) {
        Objects.requireNonNull(order, "order must not be null");
        Objects.requireNonNull(occurredAt, "occurredAt must not be null");
        String reason = normalizeReason(safeReason);
        if (orderMapper.markFailedIfProcessing(order.getId(), reason) != 1) {
            return;
        }
        outboxService.append(DrawEventEnvelope.create(
                DrawEventType.DRAW_RELEASE_REQUESTED, order.getRequestId(), order.getUserId(),
                order.getActivityId(), order.getId(), occurredAt,
                new DrawReleaseRequestedEvent(order.getDrawCount(), order.getDrawDate(), reason),
                objectMapper));
    }

    private void validateIdentity(LotteryDrawOrder order, NewDrawOrder command) {
        if (order == null
                || !Objects.equals(order.getUserId(), command.userId())
                || !Objects.equals(order.getActivityId(), command.activityId())
                || !Objects.equals(order.getDrawCount(), command.drawCount())) {
            throw new BusinessException(LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
    }

    private String normalizeReason(String reason) {
        String normalized = reason == null ? "" : reason.trim();
        if (normalized.isEmpty()) {
            normalized = DEFAULT_SAFE_REASON;
        }
        return normalized.length() <= MAX_REASON_LENGTH
                ? normalized
                : normalized.substring(0, MAX_REASON_LENGTH);
    }
}

package com.dongqh.luckyhub.service.lottery.impl;

import com.dongqh.luckyhub.domain.po.benefit.UserBenefit;
import com.dongqh.luckyhub.enums.benefit.BenefitStatus;
import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.service.inventory.ActivityPrizeInventoryService;
import com.dongqh.luckyhub.domain.algorithm.lottery.DrawCandidate;
import com.dongqh.luckyhub.domain.algorithm.lottery.PrizeWeightSnapshot;
import com.dongqh.luckyhub.domain.algorithm.lottery.WeightedDrawEngine;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.DrawResultType;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawOrderMapper;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.messaging.lottery.event.DrawConfirmedEvent;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventEnvelope;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventType;
import com.dongqh.luckyhub.messaging.lottery.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.luckyhub.domain.model.lottery.DrawExecutionContext;
import com.dongqh.luckyhub.domain.model.lottery.DrawExecutionResult;
import com.dongqh.luckyhub.domain.model.lottery.DrawPrizeSnapshot;
import com.dongqh.luckyhub.domain.model.lottery.DrawResultItem;
import com.dongqh.luckyhub.domain.model.reward.RewardSnapshot;
import com.dongqh.luckyhub.service.lottery.DrawTransactionService;
import com.dongqh.luckyhub.service.lottery.OutboxService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

import java.util.ArrayList;
import java.util.List;

@Service
public class DrawTransactionServiceImpl implements DrawTransactionService {

    private final WeightedDrawEngine drawEngine;
    private final ActivityPrizeInventoryService inventoryService;
    private final LotteryDrawOrderMapper orderMapper;
    private final LotteryDrawRecordMapper recordMapper;
    private final UserBenefitMapper benefitMapper;
    private final OutboxService outboxService;
    private final ObjectMapper objectMapper;

    public DrawTransactionServiceImpl(
            WeightedDrawEngine drawEngine,
            ActivityPrizeInventoryService inventoryService,
            LotteryDrawOrderMapper orderMapper,
            LotteryDrawRecordMapper recordMapper,
            UserBenefitMapper benefitMapper,
            OutboxService outboxService,
            ObjectMapper objectMapper) {
        this.drawEngine = drawEngine;
        this.inventoryService = inventoryService;
        this.orderMapper = orderMapper;
        this.recordMapper = recordMapper;
        this.benefitMapper = benefitMapper;
        this.outboxService = outboxService;
        this.objectMapper = objectMapper;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRED)
    public DrawExecutionResult execute(DrawExecutionContext context) {
        List<PrizeWeightSnapshot> weights = context.prizes().stream()
                .map(DrawPrizeSnapshot::toWeightSnapshot)
                .toList();
        List<DrawResultItem> results = new ArrayList<>(context.drawCount());

        for (int sequence = 1; sequence <= context.drawCount(); sequence++) {
            DrawCandidate candidate = drawEngine.select(weights, context.noWinWeight());
            DrawPrizeSnapshot wonPrize = resolveFinalWin(candidate, context.prizes());
            results.add(persistResult(context, sequence, wonPrize));
        }

        if (orderMapper.markSuccessIfProcessing(context.orderId(), context.drawTime()) != 1) {
            throw new BusinessException(LotteryErrorCode.DRAW_TRANSACTION_FAILED);
        }

        appendConfirmedEvent(context);
        results.stream()
                .filter(item -> item.resultType() == DrawResultType.WIN)
                .forEach(item -> appendFulfillmentEvent(context, item));

        return new DrawExecutionResult(
                context.orderId(), context.requestId(), DrawOrderStatus.SUCCESS,
                context.drawTime(), results);
    }

    private DrawPrizeSnapshot resolveFinalWin(
            DrawCandidate candidate,
            List<DrawPrizeSnapshot> snapshots) {
        if (candidate.type() == DrawCandidate.Type.NO_WIN) {
            return null;
        }
        DrawPrizeSnapshot snapshot = snapshots.stream()
                .filter(prize -> prize.activityPrizeId() == candidate.activityPrizeId()
                        && prize.prizeId() == candidate.prizeId())
                .findFirst()
                .orElseThrow(() -> new BusinessException(LotteryErrorCode.DRAW_TRANSACTION_FAILED));
        return inventoryService.decrementIfAvailable(snapshot.activityPrizeId()) ? snapshot : null;
    }

    private DrawResultItem persistResult(
            DrawExecutionContext context,
            int sequence,
            DrawPrizeSnapshot prize) {
        LotteryDrawRecord record = new LotteryDrawRecord();
        record.setOrderId(context.orderId());
        record.setRequestId(context.requestId());
        record.setSequenceNo(sequence);
        record.setUserId(context.userId());
        record.setActivityId(context.activityId());
        record.setResultType(prize == null ? DrawResultType.NO_WIN : DrawResultType.WIN);
        record.setDrawTime(context.drawTime());
        if (prize != null) {
            record.setPrizeId(prize.prizeId());
            record.setPrizeName(prize.prizeName());
            record.setPrizeType(prize.prizeType());
            record.setPrizeImageUrl(prize.prizeImageUrl());
            copyReward(prize.rewardSnapshot(), record);
        }
        recordMapper.insert(record);

        Long benefitId = prize == null ? null : persistPendingBenefit(context, record, prize);
        return new DrawResultItem(
                record.getId(), sequence, record.getResultType(), record.getPrizeId(),
                record.getPrizeName(), record.getPrizeType(), record.getPrizeImageUrl(), benefitId,
                prize == null ? null : prize.rewardSnapshot());
    }

    private Long persistPendingBenefit(
            DrawExecutionContext context,
            LotteryDrawRecord record,
            DrawPrizeSnapshot prize) {
        UserBenefit benefit = new UserBenefit();
        benefit.setDrawRecordId(record.getId());
        benefit.setUserId(context.userId());
        benefit.setPrizeId(prize.prizeId());
        benefit.setPrizeType(prize.prizeType());
        copyReward(prize.rewardSnapshot(), benefit);
        benefit.setQuantity(1);
        benefit.setStatus(BenefitStatus.PENDING);
        benefit.setObtainedAt(context.drawTime());
        benefitMapper.insert(benefit);
        return benefit.getId();
    }

    private void copyReward(RewardSnapshot reward, LotteryDrawRecord record) {
        if (reward == null) return;
        record.setRewardDefinitionId(reward.rewardDefinitionId());
        record.setRewardType(reward.rewardType());
        record.setRewardTargetId(reward.targetId());
        record.setRewardQuantity(reward.quantity());
        record.setRewardPayload(reward.payloadJson());
        record.setRewardFingerprint(reward.fingerprint());
    }

    private void copyReward(RewardSnapshot reward, UserBenefit benefit) {
        if (reward == null) return;
        benefit.setRewardDefinitionId(reward.rewardDefinitionId());
        benefit.setRewardType(reward.rewardType());
        benefit.setRewardTargetId(reward.targetId());
        benefit.setRewardQuantity(reward.quantity());
        benefit.setRewardPayload(reward.payloadJson());
        benefit.setRewardFingerprint(reward.fingerprint());
    }

    private void appendConfirmedEvent(DrawExecutionContext context) {
        outboxService.append(DrawEventEnvelope.create(
                DrawEventType.DRAW_CONFIRMED,
                context.requestId(), context.userId(), context.activityId(), context.orderId(),
                context.drawTime(), new DrawConfirmedEvent(context.drawCount(), context.drawDate()),
                objectMapper));
    }

    private void appendFulfillmentEvent(DrawExecutionContext context, DrawResultItem item) {
        outboxService.append(DrawEventEnvelope.create(
                DrawEventType.PRIZE_FULFILLMENT_REQUESTED,
                context.requestId(), context.userId(), context.activityId(), context.orderId(),
                context.drawTime(), new PrizeFulfillmentRequestedEvent(
                        item.benefitId(), item.recordId(), item.prizeId(), item.prizeType(),
                        item.rewardSnapshot() == null ? null : item.rewardSnapshot().rewardDefinitionId(),
                        item.rewardSnapshot() == null ? null : item.rewardSnapshot().rewardType(),
                        item.rewardSnapshot() == null ? null : item.rewardSnapshot().fingerprint()),
                objectMapper));
    }
}

package com.dongqh.luckyhub.service.lottery.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.dongqh.luckyhub.domain.po.activity.MarketingActivity;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityMapper;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityPrizeMapper;
import com.dongqh.luckyhub.domain.po.benefit.UserBenefit;
import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.common.enums.CommonErrorCode;
import com.dongqh.luckyhub.common.result.PageResponse;
import com.dongqh.luckyhub.domain.dto.lottery.DrawOrderQuery;
import com.dongqh.luckyhub.domain.dto.lottery.DrawRecordQuery;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawOrder;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawOrderMapper;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.service.lottery.LotteryQueryService;
import com.dongqh.luckyhub.domain.vo.lottery.*;
import com.dongqh.luckyhub.mapper.prize.MarketingPrizeMapper;
import com.dongqh.luckyhub.service.scope.DataScopeService;
import com.dongqh.luckyhub.service.scope.UserDataScope;
import org.springframework.stereotype.Service;

import java.util.*;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.stream.Collectors;

@Service
public class LotteryQueryServiceImpl implements LotteryQueryService {
    private static final long MAX_PAGE = 1_000_000L;
    private static final LocalDate MYSQL_MIN_DATE = LocalDate.of(1000, 1, 1);
    private static final LocalDate MAX_SAFE_END_DATE = LocalDate.of(9999, 12, 30);
    private final MarketingActivityMapper activityMapper;
    private final MarketingActivityPrizeMapper activityPrizeMapper;
    private final MarketingPrizeMapper prizeMapper;
    private final LotteryDrawOrderMapper orderMapper;
    private final LotteryDrawRecordMapper recordMapper;
    private final UserBenefitMapper benefitMapper;
    private final DataScopeService dataScopeService;

    public LotteryQueryServiceImpl(MarketingActivityMapper activityMapper, LotteryDrawOrderMapper orderMapper,
                                   LotteryDrawRecordMapper recordMapper, UserBenefitMapper benefitMapper,
                                   DataScopeService dataScopeService) {
        this(activityMapper, null, null, orderMapper, recordMapper, benefitMapper, dataScopeService);
    }

    @org.springframework.beans.factory.annotation.Autowired
    public LotteryQueryServiceImpl(MarketingActivityMapper activityMapper,
                                   MarketingActivityPrizeMapper activityPrizeMapper,
                                   MarketingPrizeMapper prizeMapper,
                                   LotteryDrawOrderMapper orderMapper,
                                   LotteryDrawRecordMapper recordMapper, UserBenefitMapper benefitMapper,
                                   DataScopeService dataScopeService) {
        this.activityMapper = activityMapper;
        this.activityPrizeMapper = activityPrizeMapper;
        this.prizeMapper = prizeMapper;
        this.orderMapper = orderMapper;
        this.recordMapper = recordMapper;
        this.benefitMapper = benefitMapper;
        this.dataScopeService = dataScopeService;
    }

    @Override
    public List<LotteryActivityView> listActivities() {
        LocalDateTime now = LocalDateTime.now();
        return activityMapper.selectList(new LambdaQueryWrapper<MarketingActivity>()
                        .eq(MarketingActivity::getStatus, com.dongqh.luckyhub.enums.activity.ActivityStatus.RUNNING)
                        .le(MarketingActivity::getStartTime, now)
                        .ge(MarketingActivity::getEndTime, now)
                        .orderByAsc(MarketingActivity::getEndTime)
                        .orderByAsc(MarketingActivity::getId)
                        .last("LIMIT 100"))
                .stream().map(activity -> new LotteryActivityView(
                        activity.getId(), activity.getActivityName(), activity.getDescription(),
                        activity.getStatus(), activity.getStartTime(), activity.getEndTime()))
                .toList();
    }

    @Override
    public List<LotteryPrizeView> listPrizes(long activityId) {
        getActivity(activityId);
        MarketingActivityPrizeMapper requiredActivityPrizes = Objects.requireNonNull(activityPrizeMapper,
                "MarketingActivityPrizeMapper is required for prize queries");
        return List.copyOf(requiredActivityPrizes.selectVisiblePrizeViews(activityId));
    }

    @Override
    public LotteryActivityView getActivity(long activityId) {
        MarketingActivity activity = activityMapper.selectById(activityId);
        if (activity == null) throw new BusinessException(LotteryErrorCode.ACTIVITY_NOT_FOUND);
        return new LotteryActivityView(activity.getId(), activity.getActivityName(), activity.getDescription(),
                activity.getStatus(), activity.getStartTime(), activity.getEndTime());
    }

    @Override
    public DrawOrderView getDraw(String requestId) {
        LotteryDrawOrder order = orderMapper.selectByRequestId(requestId);
        if (order == null) throw new BusinessException(LotteryErrorCode.DRAW_ACCESS_DENIED, "抽奖订单不存在或无权访问");
        dataScopeService.resolveUserScope(order.getUserId());
        return toOrderView(order, recordMapper.selectByOrderId(order.getId()));
    }

    @Override
    public PageResponse<DrawOrderView> pageOrders(DrawOrderQuery query) {
        validatePage(query.getPage(), query.getSize());
        validateMysqlDate(query.getDrawDate(), false);
        UserDataScope scope = dataScopeService.resolveUserScope(query.getUserId());
        LambdaQueryWrapper<LotteryDrawOrder> wrapper = new LambdaQueryWrapper<LotteryDrawOrder>()
                .eq(!scope.all(), LotteryDrawOrder::getUserId, scope.userId())
                .eq(query.getActivityId() != null, LotteryDrawOrder::getActivityId, query.getActivityId())
                .eq(query.getStatus() != null, LotteryDrawOrder::getStatus, query.getStatus())
                .eq(query.getDrawDate() != null, LotteryDrawOrder::getDrawDate, query.getDrawDate())
                .orderByDesc(LotteryDrawOrder::getCreatedAt).orderByDesc(LotteryDrawOrder::getId);
        Page<LotteryDrawOrder> page = orderMapper.selectPage(Page.of(query.getPage(), query.getSize()), wrapper);
        Map<Long, List<LotteryDrawRecord>> records = page.getRecords().isEmpty() ? Map.of()
                : recordMapper.selectByOrderIds(page.getRecords().stream().map(LotteryDrawOrder::getId).toList())
                .stream().collect(Collectors.groupingBy(LotteryDrawRecord::getOrderId));
        List<DrawOrderView> views = page.getRecords().stream()
                .map(order -> toOrderView(order, records.getOrDefault(order.getId(), List.of()))).toList();
        return new PageResponse<>(views, page.getTotal(), page.getCurrent(), page.getSize(), page.getPages());
    }

    @Override
    public PageResponse<DrawOrderView> pageMyOrders(long userId, DrawOrderQuery query) {
        query.setUserId(userId);
        return pageOrders(query);
    }

    @Override
    public PageResponse<DrawRecordView> pageRecords(DrawRecordQuery query) {
        validatePage(query.getPage(), query.getSize());
        validateMysqlDate(query.getStartDate(), false);
        validateMysqlDate(query.getEndDate(), true);
        if (query.getStartDate() != null && query.getEndDate() != null && query.getStartDate().isAfter(query.getEndDate())) {
            throw invalidQuery();
        }
        UserDataScope scope = dataScopeService.resolveUserScope(query.getUserId());
        LambdaQueryWrapper<LotteryDrawRecord> wrapper = new LambdaQueryWrapper<LotteryDrawRecord>()
                .eq(!scope.all(), LotteryDrawRecord::getUserId, scope.userId())
                .eq(query.getActivityId() != null, LotteryDrawRecord::getActivityId, query.getActivityId())
                .eq(query.getResultType() != null, LotteryDrawRecord::getResultType, query.getResultType())
                .ge(query.getStartDate() != null, LotteryDrawRecord::getDrawTime,
                        query.getStartDate() == null ? null : query.getStartDate().atStartOfDay())
                .lt(query.getEndDate() != null, LotteryDrawRecord::getDrawTime, endExclusive(query.getEndDate()))
                .orderByDesc(LotteryDrawRecord::getDrawTime).orderByDesc(LotteryDrawRecord::getId);
        Page<LotteryDrawRecord> page = recordMapper.selectPage(Page.of(query.getPage(), query.getSize()), wrapper);
        Map<Long, Long> benefits = benefitIds(page.getRecords());
        List<DrawRecordView> views = page.getRecords().stream().map(record -> toRecordView(record, benefits.get(record.getId()))).toList();
        return new PageResponse<>(views, page.getTotal(), page.getCurrent(), page.getSize(), page.getPages());
    }

    private void validatePage(long page, long size) {
        if (page < 1 || page > MAX_PAGE || size < 1 || size > 100) throw invalidQuery();
        try { Math.multiplyExact(page - 1, size); } catch (ArithmeticException exception) { throw invalidQuery(); }
    }

    private void validateMysqlDate(LocalDate date, boolean safeEnd) {
        if (date == null) return;
        LocalDate maximum = safeEnd ? MAX_SAFE_END_DATE : MAX_SAFE_END_DATE.plusDays(1);
        if (date.isBefore(MYSQL_MIN_DATE) || date.isAfter(maximum)) throw invalidQuery();
    }

    private LocalDateTime endExclusive(LocalDate endDate) {
        return endDate == null ? null : endDate.plusDays(1).atStartOfDay();
    }

    private BusinessException invalidQuery() {
        return new BusinessException(CommonErrorCode.INVALID_PARAMETER, "查询条件超出支持范围");
    }

    private Map<Long, Long> benefitIds(List<LotteryDrawRecord> records) {
        if (records.isEmpty()) return Map.of();
        List<Long> ids = records.stream().map(LotteryDrawRecord::getId).toList();
        return benefitMapper.selectList(new LambdaQueryWrapper<UserBenefit>().in(UserBenefit::getDrawRecordId, ids))
                .stream().collect(Collectors.toMap(UserBenefit::getDrawRecordId, UserBenefit::getId));
    }

    private DrawOrderView toOrderView(LotteryDrawOrder order, List<LotteryDrawRecord> records) {
        List<DrawResultView> results = records.stream().map(record -> new DrawResultView(record.getId(), record.getSequenceNo(),
                record.getResultType(), record.getPrizeId(), record.getPrizeName(), record.getPrizeType(),
                record.getPrizeImageUrl(), record.getBenefitId(),
                record.getRewardType() == com.dongqh.luckyhub.enums.reward.RewardType.PRODUCT
                        ? record.getRewardTargetId() : null)).toList();
        return new DrawOrderView(order.getId(), order.getRequestId(), order.getActivityId(), order.getDrawCount(),
                order.getDrawDate(), order.getStatus(), order.getFailReason(), order.getCompletedAt(), results);
    }

    private DrawRecordView toRecordView(LotteryDrawRecord record, Long benefitId) {
        return new DrawRecordView(record.getId(), record.getOrderId(), record.getRequestId(), record.getSequenceNo(),
                record.getUserId(), record.getActivityId(), record.getResultType(), record.getPrizeId(), record.getPrizeName(),
                record.getPrizeType(), record.getPrizeImageUrl(), benefitId, record.getDrawTime());
    }
}

