import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CatalogControllerTests {

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private CatalogService service;

    @MockitoBean
    private JwtService jwtService;

    @MockitoBean
    private SessionService sessionService;

    @MockitoBean
    private UserPermissionService userPermissionService;

    @BeforeEach
    void prepareCaller() {
        when(jwtService.parse("valid-token")).thenReturn(new JwtPayload(7711L, "catalog-user", "session-1"));
        when(sessionService.isValid("session-1", 7711L)).thenReturn(true);
    }

    @Test
    void createsProductWithManagePermission() throws Exception {
        when(userPermissionService.findPermissionCodes(7711L)).thenReturn(Set.of(PermissionCodes.CATALOG_MANAGE));
        when(service.create(any())).thenReturn(view());

        mockMvc.perform(post("/api/admin/products")
                        .header("Authorization", "Bearer valid-token")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(validBody()))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.data.id").value(7));
    }

    @Test
    void readsProductsWithReadPermissionWithoutInventoryFields() throws Exception {
        when(userPermissionService.findPermissionCodes(7711L)).thenReturn(Set.of(PermissionCodes.CATALOG_READ));
        when(service.page(any())).thenReturn(new PageResponse<>(List.of(view()), 1, 1, 20, 1));
        when(service.get(7L)).thenReturn(view());

        mockMvc.perform(get("/api/products")
                        .header("Authorization", "Bearer valid-token"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.data.records[0].skus[0].cashPriceCent").value(1999))
                .andExpect(jsonPath("$.data.records[0].skus[0].pointsEnabled").value(true))
                .andExpect(jsonPath("$.data.records[0].skus[0].availableStock").doesNotExist());
        mockMvc.perform(get("/api/products/7")
                        .header("Authorization", "Bearer valid-token"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.data.productCode").value("PROD-1"));
    }

    @Test
    void rejectsInvalidCommandWithValidationEnvelope() throws Exception {
        when(userPermissionService.findPermissionCodes(7711L)).thenReturn(Set.of(PermissionCodes.CATALOG_MANAGE));
        String invalidBody = validBody().replace("测试商品", "");

        mockMvc.perform(post("/api/admin/products")
                        .header("Authorization", "Bearer valid-token")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(invalidBody))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value(30000));
    }

    @Test
    void realFilterAndPermissionInterceptorReturn401And403() throws Exception {
        when(userPermissionService.findPermissionCodes(7711L)).thenReturn(Set.of());

        mockMvc.perform(get("/api/products")).andExpect(status().isUnauthorized());
        mockMvc.perform(get("/api/products").header("Authorization", "Bearer valid-token"))
                .andExpect(status().isForbidden());
        mockMvc.perform(post("/api/admin/products")
                        .header("Authorization", "Bearer valid-token")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(validBody()))
                .andExpect(status().isForbidden());
    }

    @Test
    void assignsExactPermissions() throws NoSuchMethodException {
        Method create = CatalogAdminController.class.getMethod(
                "create", com.dongqh.luckyhub.domain.dto.catalog.CreateProductCommand.class);
        Method page = CatalogController.class.getMethod(
                "page", com.dongqh.luckyhub.domain.dto.catalog.ProductQuery.class);
        Method getById = CatalogController.class.getMethod("get", long.class);

        assertThat(create.getAnnotation(RequirePermission.class).value()).isEqualTo(PermissionCodes.CATALOG_MANAGE);
        assertThat(page.getAnnotation(RequirePermission.class).value()).isEqualTo(PermissionCodes.CATALOG_READ);
        assertThat(getById.getAnnotation(RequirePermission.class).value()).isEqualTo(PermissionCodes.CATALOG_READ);
    }

    private ProductView view() {
        SkuView sku = new SkuView(8L, 7L, "SKU-1", "默认SKU", 1999L, 2000L,
                true, true, 1, 0, null, null);
        return new ProductView(7L, "PROD-1", "测试商品", ProductType.PHYSICAL,
                "https://cdn.example/product.png", "商品说明", 1, List.of(sku), null, null);
    }

    private String validBody() {
        return """
                {
                  "productCode": "PROD-1",
                  "productName": "测试商品",
                  "productType": "PHYSICAL",
                  "skuCode": "SKU-1",
                  "skuName": "默认SKU",
                  "cashPriceCent": 1999,
                  "pointsPrice": 2000,
                  "cashEnabled": true,
                  "pointsEnabled": true
                }
                """;
    }
}

package com.dongqh.luckyhub.catalog;

import com.dongqh.luckyhub.domain.po.catalog.Product;
import com.dongqh.luckyhub.domain.po.catalog.ProductSku;
import com.dongqh.luckyhub.enums.catalog.ProductType;
import com.dongqh.luckyhub.mapper.catalog.ProductMapper;
import com.dongqh.luckyhub.mapper.catalog.ProductSkuMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class CatalogDomainContractTests {

    @Autowired ProductMapper productMapper;
    @Autowired ProductSkuMapper skuMapper;

    private Long productId;
    private Long skuId;

    @AfterEach
    void cleanUp() {
        if (skuId != null) {
            skuMapper.deleteById(skuId);
        }
        if (productId != null) {
            productMapper.deleteById(productId);
        }
    }

    @Test
    void exposesStableProductTypes() {
        assertThat(ProductType.values()).containsExactly(
                ProductType.PHYSICAL, ProductType.VIRTUAL);
    }

    @Test
    void persistsProductAndSkuBusinessFields() {
        String suffix = UUID.randomUUID().toString();
        Product product = new Product();
        product.setProductCode("PRODUCT-" + suffix);
        product.setProductName("测试保温杯");
        product.setProductType(ProductType.PHYSICAL);
        product.setImageUrl("https://cdn.example/product.png");
        product.setDescription("商品领域契约测试");
        product.setStatus(1);
        productMapper.insert(product);
        productId = product.getId();

        ProductSku sku = new ProductSku();
        sku.setProductId(productId);
        sku.setSkuCode("SKU-" + suffix);
        sku.setSkuName("默认规格");
        sku.setCashPriceCent(12_345L);
        sku.setPointsPrice(9_900L);
        sku.setCashEnabled(true);
        sku.setPointsEnabled(true);
        sku.setStatus(1);
        sku.setVersion(0);
        skuMapper.insert(sku);
        skuId = sku.getId();

        Product persistedProduct = productMapper.selectById(productId);
        ProductSku persistedSku = skuMapper.selectById(skuId);

        assertThat(persistedProduct.getProductCode()).isEqualTo(product.getProductCode());
        assertThat(persistedProduct.getProductName()).isEqualTo("测试保温杯");
        assertThat(persistedProduct.getProductType()).isEqualTo(ProductType.PHYSICAL);
        assertThat(persistedProduct.getImageUrl()).isEqualTo("https://cdn.example/product.png");
        assertThat(persistedProduct.getDescription()).isEqualTo("商品领域契约测试");
        assertThat(persistedProduct.getStatus()).isOne();
        assertThat(persistedProduct.getCreatedAt()).isNotNull();
        assertThat(persistedProduct.getUpdatedAt()).isNotNull();

        assertThat(persistedSku.getProductId()).isEqualTo(productId);
        assertThat(persistedSku.getSkuCode()).isEqualTo(sku.getSkuCode());
        assertThat(persistedSku.getSkuName()).isEqualTo("默认规格");
        assertThat(persistedSku.getCashPriceCent()).isEqualTo(12_345L);
        assertThat(persistedSku.getPointsPrice()).isEqualTo(9_900L);
        assertThat(persistedSku.getCashEnabled()).isTrue();
        assertThat(persistedSku.getPointsEnabled()).isTrue();
        assertThat(persistedSku.getStatus()).isOne();
        assertThat(persistedSku.getVersion()).isZero();
        assertThat(persistedSku.getCreatedAt()).isNotNull();
        assertThat(persistedSku.getUpdatedAt()).isNotNull();
    }
}

package com.dongqh.luckyhub.catalog;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class CatalogRewardSchemaContractTests {

    @Autowired
    JdbcTemplate jdbcTemplate;

    @Test
    void createsCatalogRewardTablesAndCompatibilityLink() {
        assertThat(tableExists("product")).isTrue();
        assertThat(tableExists("product_sku")).isTrue();
        assertThat(tableExists("reward_definition")).isTrue();
        assertThat(columnExists("marketing_prize", "reward_definition_id")).isTrue();
    }

    @Test
    void seedsCatalogRewardAndInventoryPermissions() {
        List<String> permissions = jdbcTemplate.queryForList("""
                SELECT permission_code FROM sys_permission
                WHERE permission_code IN (
                    'catalog:read', 'catalog:manage', 'reward:manage', 'inventory:manage'
                )
                """, String.class);
        assertThat(permissions).containsExactlyInAnyOrder(
                "catalog:read", "catalog:manage", "reward:manage", "inventory:manage");
    }

    @Test
    void grantsReadToUserAndAllNewPermissionsToAdmin() {
        assertThat(rolePermissions("USER")).contains("catalog:read");
        assertThat(rolePermissions("ADMIN")).contains(
                "catalog:read", "catalog:manage", "reward:manage", "inventory:manage");
    }

    private boolean tableExists(String tableName) {
        Integer count = jdbcTemplate.queryForObject("""
                SELECT COUNT(*) FROM information_schema.tables
                WHERE table_schema = DATABASE() AND table_name = ?
                """, Integer.class, tableName);
        return count != null && count == 1;
    }

    private boolean columnExists(String tableName, String columnName) {
        Integer count = jdbcTemplate.queryForObject("""
                SELECT COUNT(*) FROM information_schema.columns
                WHERE table_schema = DATABASE() AND table_name = ? AND column_name = ?
                """, Integer.class, tableName, columnName);
        return count != null && count == 1;
    }

    private List<String> rolePermissions(String roleCode) {
        return jdbcTemplate.queryForList("""
                SELECT permission.permission_code
                FROM sys_role_permission relation
                JOIN sys_role role_record ON role_record.id = relation.role_id
                JOIN sys_permission permission ON permission.id = relation.permission_id
                WHERE role_record.role_code = ?
                """, String.class, roleCode);
    }
}

package com.dongqh.luckyhub.catalog;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.domain.dto.catalog.CreateProductCommand;
import com.dongqh.luckyhub.domain.dto.catalog.ProductQuery;
import com.dongqh.luckyhub.domain.po.catalog.Product;
import com.dongqh.luckyhub.domain.po.catalog.ProductSku;
import com.dongqh.luckyhub.enums.catalog.ProductErrorCode;
import com.dongqh.luckyhub.enums.catalog.ProductType;
import com.dongqh.luckyhub.mapper.catalog.ProductMapper;
import com.dongqh.luckyhub.mapper.catalog.ProductSkuMapper;
import com.dongqh.luckyhub.service.catalog.CatalogService;
import com.dongqh.luckyhub.common.exception.BusinessException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class CatalogServiceTests {

    @Autowired
    private CatalogService service;

    @Autowired
    private ProductMapper productMapper;

    @Autowired
    private ProductSkuMapper skuMapper;

    @BeforeEach
    void cleanTables() {
        skuMapper.delete(new LambdaQueryWrapper<>());
        productMapper.delete(new LambdaQueryWrapper<>());
    }

    @Test
    void commandAcceptsEveryPurchaseModeAndRejectsInvalidCombinations() {
        assertThat(command("P-CASH", "S-CASH", true, false)).isNotNull();
        assertThat(command("P-POINTS", "S-POINTS", false, true)).isNotNull();
        assertThat(command("P-BOTH", "S-BOTH", true, true)).isNotNull();

        assertThatThrownBy(() -> new CreateProductCommand(
                "P1", "商品", ProductType.PHYSICAL, null, null,
                "S1", "SKU", null, 100L, true, true))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new CreateProductCommand(
                "P1", "商品", ProductType.PHYSICAL, null, null,
                "S1", "SKU", 100L, null, true, true))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new CreateProductCommand(
                "P1", "商品", ProductType.PHYSICAL, null, null,
                "S1", "SKU", null, null, false, false))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void createsOneProductAndOneDefaultSkuAndReturnsSnapshots() {
        var created = service.create(command("  PROD-1 ", " SKU-1 ", true, true));

        assertThat(productMapper.selectCount(new LambdaQueryWrapper<>())).isEqualTo(1);
        assertThat(skuMapper.selectCount(new LambdaQueryWrapper<>())).isEqualTo(1);
        assertThat(created.productCode()).isEqualTo("PROD-1");
        assertThat(created.skus()).singleElement().satisfies(sku -> {
            assertThat(sku.skuCode()).isEqualTo("SKU-1");
            assertThat(sku.cashPriceCent()).isEqualTo(1999L);
            assertThat(sku.pointsPrice()).isEqualTo(2000L);
            assertThat(sku.cashEnabled()).isTrue();
            assertThat(sku.pointsEnabled()).isTrue();
        });
        var detail = service.get(created.id());
        assertThat(detail.productCode()).isEqualTo(created.productCode());
        assertThat(detail.productName()).isEqualTo(created.productName());
        assertThat(detail.skus()).extracting(sku -> sku.skuCode()).containsExactly("SKU-1");
        assertThat(detail.createdAt()).isNotNull();
        assertThat(detail.skus().get(0).createdAt()).isNotNull();
    }

    @Test
    void translatesDuplicateProductAndSkuCodesAndRollsBackPartialProduct() {
        service.create(command("PROD-1", "SKU-1", true, false));

        assertThatThrownBy(() -> service.create(command(" PROD-1 ", "SKU-2", true, false)))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(ProductErrorCode.PRODUCT_CODE_DUPLICATE));

        assertThatThrownBy(() -> service.create(command("PROD-2", " SKU-1 ", true, false)))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(ProductErrorCode.SKU_CODE_DUPLICATE));

        assertThat(productMapper.selectCount(new LambdaQueryWrapper<>())).isEqualTo(1);
        assertThat(productMapper.selectOne(new LambdaQueryWrapper<Product>()
                .eq(Product::getProductCode, "PROD-2"))).isNull();
    }

    @Test
    void userPageHidesDisabledProducts() {
        var enabled = service.create(command("PROD-1", "SKU-1", true, false));
        var disabled = service.create(command("PROD-2", "SKU-2", false, true));
        Product entity = productMapper.selectById(disabled.id());
        entity.setStatus(0);
        productMapper.updateById(entity);

        ProductQuery query = new ProductQuery();
        var page = service.page(query);

        assertThat(page.records()).extracting(view -> view.id()).containsExactly(enabled.id());
        assertThat(page.records().get(0).skus()).hasSize(1);
    }

    @Test
    void missingProductUsesStableError() {
        assertThatThrownBy(() -> service.get(Long.MAX_VALUE))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(ProductErrorCode.PRODUCT_NOT_FOUND));
    }

    private CreateProductCommand command(String productCode, String skuCode,
                                         boolean cashEnabled, boolean pointsEnabled) {
        return new CreateProductCommand(
                productCode,
                " 测试商品 ",
                ProductType.PHYSICAL,
                " https://cdn.example/product.png ",
                " 商品说明 ",
                skuCode,
                " 默认SKU ",
                cashEnabled ? 1999L : null,
                pointsEnabled ? 2000L : null,
                cashEnabled,
                pointsEnabled
        );
    }
}

