        mockMvc.perform(post("/test/validation")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{broken-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value(30001))
                .andExpect(jsonPath("$.message").value("请求内容格式错误"));
    }

    @Test
