package com.dongqh.luckyhub.integration;

import com.dongqh.luckyhub.enums.fulfillment.FulfillmentType;
import com.dongqh.luckyhub.enums.fulfillment.GatewayOutcome;
import com.dongqh.luckyhub.domain.gateway.integration.*;
import com.dongqh.luckyhub.domain.simulator.integration.SimulatorFailureMode;
import com.dongqh.luckyhub.domain.simulator.integration.SimulatorFailureRuleService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class SimulatorGatewayTests {
    @Autowired CouponGateway couponGateway; @Autowired PointsGateway pointsGateway;
    @Autowired MembershipGateway membershipGateway; @Autowired LogisticsGateway logisticsGateway;
    @Autowired SimulatorFailureRuleService rules; @Autowired JdbcTemplate jdbc;

    @AfterEach void clean() {
        jdbc.update("DELETE FROM sim_coupon_record"); jdbc.update("DELETE FROM sim_points_record");
        jdbc.update("DELETE FROM sim_membership_record"); jdbc.update("DELETE FROM sim_logistics_record");
        jdbc.update("DELETE FROM sim_failure_rule");
    }

    @Test void executesAndQueriesAllFourProviders() {
        String suffix=UUID.randomUUID().toString();
        GatewayResult coupon=couponGateway.execute(new CouponGrantRequest("C-"+suffix,1L,"NEW20",1));
        GatewayResult points=pointsGateway.execute(new PointsGrantRequest("P-"+suffix,1L,500,"奖励"));
        GatewayResult member=membershipGateway.execute(new MembershipGrantRequest("M-"+suffix,1L,"VIP",30));
        GatewayResult logistics=logisticsGateway.execute(new LogisticsCreateRequest(
                "L-"+suffix,1L,99L,"SKU-1",1,"李四","13912341234",
                "上海市","上海市","浦东新区","世纪大道1号",
                "李*","139****1234","上海市浦东新区***"));
        assertThat(coupon.outcome()).isEqualTo(GatewayOutcome.SUCCEEDED);
        assertThat(points.outcome()).isEqualTo(GatewayOutcome.SUCCEEDED);
        assertThat(member.outcome()).isEqualTo(GatewayOutcome.SUCCEEDED);
        assertThat(logistics.outcome()).isEqualTo(GatewayOutcome.SUCCEEDED);
        assertThat(couponGateway.query("C-"+suffix).externalReference()).isEqualTo(coupon.externalReference());
        assertThat(logisticsGateway.query("missing").outcome()).isEqualTo(GatewayOutcome.NOT_FOUND);
    }

    @Test void duplicateExecuteIsIdempotentButChangedPayloadConflicts() {
        CouponGrantRequest request=new CouponGrantRequest("IDEM-1",1L,"NEW20",1);
        GatewayResult first=couponGateway.execute(request); GatewayResult second=couponGateway.execute(request);
        GatewayResult conflict=couponGateway.execute(new CouponGrantRequest("IDEM-1",1L,"NEW50",1));
        assertThat(second).isEqualTo(first);
        assertThat(conflict.outcome()).isEqualTo(GatewayOutcome.PERMANENT_FAILURE);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sim_coupon_record WHERE fulfillment_no='IDEM-1'",Integer.class)).isOne();
    }

    @Test void injectsRetryablePermanentAndUnknownBeforeWithoutSideEffects() {
        rules.configure(FulfillmentType.POINTS, SimulatorFailureMode.RETRYABLE,1);
        assertThat(pointsGateway.execute(new PointsGrantRequest("FAIL-R",1L,1,"test")).outcome()).isEqualTo(GatewayOutcome.RETRYABLE_FAILURE);
        rules.configure(FulfillmentType.POINTS, SimulatorFailureMode.PERMANENT,1);
        assertThat(pointsGateway.execute(new PointsGrantRequest("FAIL-P",1L,1,"test")).outcome()).isEqualTo(GatewayOutcome.PERMANENT_FAILURE);
        rules.configure(FulfillmentType.POINTS, SimulatorFailureMode.UNKNOWN_BEFORE,1);
        assertThat(pointsGateway.execute(new PointsGrantRequest("FAIL-U",1L,1,"test")).outcome()).isEqualTo(GatewayOutcome.UNKNOWN);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sim_points_record",Integer.class)).isZero();
    }

    @Test void unknownAfterSuccessCanBeReconciledByQuery() {
        rules.configure(FulfillmentType.MEMBERSHIP, SimulatorFailureMode.UNKNOWN_AFTER_SUCCESS,1);
        GatewayResult response=membershipGateway.execute(new MembershipGrantRequest("LOST-1",1L,"VIP",30));
        GatewayResult query=membershipGateway.query("LOST-1");
        assertThat(response.outcome()).isEqualTo(GatewayOutcome.UNKNOWN);
        assertThat(query.outcome()).isEqualTo(GatewayOutcome.SUCCEEDED);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sim_membership_record WHERE fulfillment_no='LOST-1'",Integer.class)).isOne();
    }
}

package com.dongqh.luckyhub.inventory;

import com.dongqh.luckyhub.domain.po.activity.MarketingActivityPrize;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityPrizeMapper;
import com.dongqh.luckyhub.service.inventory.ActivityPrizeInventoryService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertTimeoutPreemptively;

@SpringBootTest
class ActivityPrizeInventoryTests {

    private final ActivityPrizeInventoryService inventoryService;
    private final MarketingActivityPrizeMapper activityPrizeMapper;
    private final JdbcTemplate jdbcTemplate;
    private Long activityPrizeId;

    @Autowired
    ActivityPrizeInventoryTests(
            ActivityPrizeInventoryService inventoryService,
            MarketingActivityPrizeMapper activityPrizeMapper,
            JdbcTemplate jdbcTemplate
    ) {
        this.inventoryService = inventoryService;
        this.activityPrizeMapper = activityPrizeMapper;
        this.jdbcTemplate = jdbcTemplate;
    }

    @AfterEach
    void cleanUpCommittedTestData() {
        if (activityPrizeId != null) {
            activityPrizeMapper.deleteById(activityPrizeId);
        }
    }

    @Test
    void oneHundredConcurrentAttemptsCanConsumeStockTenTimesOnly() {
        MarketingActivityPrize relation = new MarketingActivityPrize();
        long uniqueValue = positiveRandomLong();
        relation.setActivityId(uniqueValue);
        relation.setPrizeId(uniqueValue);
        relation.setWeight(1);
        relation.setTotalStock(10);
        relation.setRemainingStock(10);
        relation.setSortOrder(0);
        activityPrizeMapper.insert(relation);
        activityPrizeId = relation.getId();

        List<Attempt> attempts = assertTimeoutPreemptively(
                Duration.ofSeconds(30),
                () -> runConcurrentAttempts(100)
        );

        assertThat(attempts).filteredOn(Attempt::decremented).hasSize(10);
        assertThat(attempts).extracting(Attempt::observedStock).allMatch(stock -> stock >= 0);
        assertThat(remainingStock()).isZero();
        assertThat(inventoryService.decrementIfAvailable(activityPrizeId)).isFalse();
        assertThat(remainingStock()).isZero();
    }

    private List<Attempt> runConcurrentAttempts(int count) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(count);
        CountDownLatch ready = new CountDownLatch(count);
        CountDownLatch start = new CountDownLatch(1);
        try {
            List<Future<Attempt>> futures = new ArrayList<>();
            for (int index = 0; index < count; index++) {
                futures.add(executor.submit(() -> {
                    ready.countDown();
                    start.await();
                    boolean decremented = inventoryService.decrementIfAvailable(activityPrizeId);
                    return new Attempt(decremented, remainingStock());
                }));
            }
            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
            start.countDown();

            List<Attempt> attempts = new ArrayList<>();
            for (Future<Attempt> future : futures) {
                attempts.add(future.get(20, TimeUnit.SECONDS));
            }
            return attempts;
        } finally {
            start.countDown();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    private int remainingStock() {
        return jdbcTemplate.queryForObject(
                "SELECT remaining_stock FROM marketing_activity_prize WHERE id = ?",
                Integer.class,
                activityPrizeId
        );
    }

    private long positiveRandomLong() {
        long value = UUID.randomUUID().getMostSignificantBits() & Long.MAX_VALUE;
        return value == 0 ? 1 : value;
    }

    private record Attempt(boolean decremented, int observedStock) {
    }
}

package com.dongqh.luckyhub.inventory;

import com.dongqh.luckyhub.domain.po.catalog.Product;
import com.dongqh.luckyhub.domain.po.catalog.ProductSku;
import com.dongqh.luckyhub.enums.catalog.ProductType;
import com.dongqh.luckyhub.mapper.catalog.ProductMapper;
import com.dongqh.luckyhub.mapper.catalog.ProductSkuMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.channel.inventory.dto.AllocateChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.InitializeSkuStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.ReserveChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.enums.ChannelInventoryErrorCode;
import com.dongqh.luckyhub.domain.channel.inventory.enums.InventoryReservationStatus;
import com.dongqh.luckyhub.domain.channel.inventory.service.ChannelInventoryService;
import com.dongqh.luckyhub.domain.channel.inventory.vo.ChannelInventoryView;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertTimeoutPreemptively;

@SpringBootTest
class ChannelInventoryConcurrencyTests {

    @Autowired
    private ChannelInventoryService service;
    @Autowired
    private ProductMapper productMapper;
    @Autowired
    private ProductSkuMapper skuMapper;
    @Autowired
    private JdbcTemplate jdbcTemplate;

    private ExecutorService executor;

    @BeforeEach
    void setUp() {
        jdbcTemplate.update("DELETE FROM inventory_ledger");
        jdbcTemplate.update("DELETE FROM inventory_reservation");
        jdbcTemplate.update("DELETE FROM inventory_channel_stock");
        jdbcTemplate.update("DELETE FROM sku_inventory");
        jdbcTemplate.update("DELETE FROM product_sku");
        jdbcTemplate.update("DELETE FROM product");
        executor = Executors.newFixedThreadPool(20);
    }

    @AfterEach
    void tearDown() {
        executor.shutdownNow();
    }

    @Test
    void oneHundredConcurrentReservationsConsumeOnlyTenAvailableUnits() {
        assertTimeoutPreemptively(Duration.ofSeconds(30), () -> {
            long skuId = initializedAndAllocatedSku(20, 10);
            CountDownLatch start = new CountDownLatch(1);
            ConcurrentLinkedQueue<Throwable> unexpected = new ConcurrentLinkedQueue<>();
            List<Future<Boolean>> futures = new ArrayList<>();
            for (int i = 0; i < 100; i++) {
                String reservationNo = "CONCURRENT-" + i;
                futures.add(executor.submit(() -> {
                    start.await();
                    try {
                        service.reserve(new ReserveChannelStockCommand(skuId, "MALL", 1, reservationNo));
                        return true;
                    } catch (BusinessException exception) {
                        if (exception.getErrorCode() != ChannelInventoryErrorCode.INVENTORY_INSUFFICIENT) {
                            unexpected.add(exception);
                        }
                        return false;
                    }
                }));
            }

            start.countDown();
            int successes = 0;
            for (Future<Boolean> future : futures) {
                if (future.get()) {
                    successes++;
                }
            }

            var inventory = service.get(skuId, "MALL");
            assertThat(unexpected).isEmpty();
            assertThat(successes).isEqualTo(10);
            assertThat(inventory.availableStock()).isZero();
            assertThat(inventory.reservedStock()).isEqualTo(10);
            assertThat(inventory.consumedStock()).isZero();
            assertThat(jdbcTemplate.queryForObject(
                    "SELECT MIN(available_stock) FROM inventory_channel_stock", Integer.class)).isZero();
        });
    }

    @Test
    void concurrentDuplicateReservationMutatesStockOnce() {
        assertTimeoutPreemptively(Duration.ofSeconds(30), () -> {
            long skuId = initializedAndAllocatedSku(20, 10);
            CountDownLatch start = new CountDownLatch(1);
            List<Future<?>> futures = new ArrayList<>();
            for (int i = 0; i < 20; i++) {
                futures.add(executor.submit(() -> {
                    start.await();
                    service.reserve(new ReserveChannelStockCommand(skuId, "mall", 1, "SAME-RES"));
                    return null;
                }));
            }

            start.countDown();
            for (Future<?> future : futures) {
                future.get();
            }

            var inventory = service.get(skuId, "MALL");
            assertThat(inventory.availableStock()).isEqualTo(9);
            assertThat(inventory.reservedStock()).isEqualTo(1);
            assertThat(count("inventory_reservation", "reservation_no", "SAME-RES")).isEqualTo(1);
            assertThat(count("inventory_ledger", "business_no", "RESERVE:SAME-RES")).isEqualTo(1);
        });
    }

    @Test
    void twentyConcurrentConfirmedReversalsRestoreConsumedStockOnce() {
        assertTimeoutPreemptively(Duration.ofSeconds(30), () -> {
            long skuId = initializedAndAllocatedSku(20, 10);
            service.reserve(new ReserveChannelStockCommand(
                    skuId, "MALL", 1, "SAME-RETURN"));
            service.confirm("SAME-RETURN");
            CountDownLatch ready = new CountDownLatch(20);
            CountDownLatch start = new CountDownLatch(1);
            List<Future<ChannelInventoryView>> futures = new ArrayList<>();

            for (int i = 0; i < 20; i++) {
                futures.add(executor.submit(() -> {
                    ready.countDown();
                    start.await();
                    return service.reverseConfirmed("SAME-RETURN");
                }));
            }

            assertThat(ready.await(10, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
            start.countDown();
            for (Future<ChannelInventoryView> future : futures) {
                assertThat(future.get().reservationStatus())
                        .isEqualTo(InventoryReservationStatus.REVERSED);
            }

            var inventory = service.get(skuId, "MALL");
            assertThat(inventory.availableStock()).isEqualTo(10);
            assertThat(inventory.reservedStock()).isZero();
            assertThat(inventory.consumedStock()).isZero();
            assertThat(count("inventory_ledger", "business_no", "RETURN:SAME-RETURN")).isEqualTo(1);
        });
    }

    private long initializedAndAllocatedSku(int total, int allocated) {
        long skuId = createSku();
        service.initialize(new InitializeSkuStockCommand(skuId, total, "INIT-CONCURRENT-" + skuId));
        service.allocate(new AllocateChannelStockCommand(
                skuId, "MALL", allocated, "ALLOC-CONCURRENT-" + skuId));
        return skuId;
    }

    private long createSku() {
        Product product = new Product();
        product.setProductCode("CONCURRENT-PROD-" + System.nanoTime());
        product.setProductName("并发库存商品");
        product.setProductType(ProductType.PHYSICAL);
        product.setStatus(1);
        productMapper.insert(product);

        ProductSku sku = new ProductSku();
        sku.setProductId(product.getId());
        sku.setSkuCode("CONCURRENT-SKU-" + System.nanoTime());
        sku.setSkuName("并发库存SKU");
        sku.setCashPriceCent(100L);
        sku.setCashEnabled(true);
        sku.setPointsEnabled(false);
        sku.setStatus(1);
        sku.setVersion(0);
        skuMapper.insert(sku);
        return sku.getId();
    }

    private int count(String table, String column, String value) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM " + table + " WHERE " + column + " = ?", Integer.class, value);
        return count == null ? 0 : count;
    }
}

