package com.dongqh.luckyhub.inventory;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class ChannelInventorySchemaContractTests {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Test
    void createsTotalChannelReservationAndLedgerTables() {
        assertThat(tableExists("sku_inventory")).isTrue();
        assertThat(tableExists("inventory_channel_stock")).isTrue();
        assertThat(tableExists("inventory_reservation")).isTrue();
        assertThat(tableExists("inventory_ledger")).isTrue();
    }

    @Test
    void createsIdempotencyAndBusinessUniquenessIndexes() {
        assertThat(uniqueIndexes()).contains(
                "sku_inventory:sku_id",
                "inventory_channel_stock:sku_id,channel_code",
                "inventory_reservation:reservation_no",
                "inventory_ledger:business_no"
        );
    }

    @Test
    void recordsSuccessfulVersionNineMigration() {
        Integer successfulMigrations = jdbcTemplate.queryForObject("""
                SELECT COUNT(*) FROM flyway_schema_history
                WHERE version = '9' AND success = 1
                """, Integer.class);

        assertThat(successfulMigrations).isEqualTo(1);
    }

    private boolean tableExists(String tableName) {
        Integer count = jdbcTemplate.queryForObject("""
                SELECT COUNT(*) FROM information_schema.tables
                WHERE table_schema = DATABASE() AND table_name = ?
                """, Integer.class, tableName);
        return count != null && count == 1;
    }

    private List<String> uniqueIndexes() {
        return jdbcTemplate.queryForList("""
                SELECT CONCAT(table_name, ':', GROUP_CONCAT(column_name ORDER BY seq_in_index))
                FROM information_schema.statistics
                WHERE table_schema = DATABASE() AND non_unique = 0
                GROUP BY table_name, index_name
                """, String.class);
    }
}

package com.dongqh.luckyhub.inventory;

import com.dongqh.luckyhub.domain.po.catalog.Product;
import com.dongqh.luckyhub.domain.po.catalog.ProductSku;
import com.dongqh.luckyhub.enums.catalog.ProductType;
import com.dongqh.luckyhub.mapper.catalog.ProductMapper;
import com.dongqh.luckyhub.mapper.catalog.ProductSkuMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.channel.inventory.dto.AllocateChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.InitializeSkuStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.ReserveChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.enums.ChannelInventoryErrorCode;
import com.dongqh.luckyhub.domain.channel.inventory.enums.InventoryReservationStatus;
import com.dongqh.luckyhub.domain.channel.inventory.service.ChannelInventoryService;
import com.dongqh.luckyhub.service.inventory.ActivityPrizeInventoryService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class ChannelInventoryServiceTests {

    @Autowired
    private ChannelInventoryService service;

    @Autowired
    private ActivityPrizeInventoryService legacyInventoryService;

    @Autowired
    private ProductMapper productMapper;

    @Autowired
    private ProductSkuMapper skuMapper;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanTables() {
        jdbcTemplate.update("DELETE FROM inventory_ledger");
        jdbcTemplate.update("DELETE FROM inventory_reservation");
        jdbcTemplate.update("DELETE FROM inventory_channel_stock");
        jdbcTemplate.update("DELETE FROM sku_inventory");
        jdbcTemplate.update("DELETE FROM product_sku");
        jdbcTemplate.update("DELETE FROM product");
    }

    @Test
    void initializesOnceAndValidatesIdempotencyIdentity() {
        long skuId = createSku(1);

        var first = service.initialize(new InitializeSkuStockCommand(skuId, 20, " INIT-1 "));
        var repeated = service.initialize(new InitializeSkuStockCommand(skuId, 20, "INIT-1"));

        assertThat(first.totalStock()).isEqualTo(20);
        assertThat(repeated.totalStock()).isEqualTo(20);
        assertThat(count("sku_inventory")).isEqualTo(1);
        assertThat(countLedger("INIT-1")).isEqualTo(1);
        assertThatThrownBy(() -> service.initialize(new InitializeSkuStockCommand(skuId, 21, "INIT-1")))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(ChannelInventoryErrorCode.INVENTORY_IDEMPOTENCY_CONFLICT));
        assertThat(legacyInventoryService).isNotSameAs(service);
    }

    @Test
    void rejectsMissingOrDisabledSku() {
        assertError(() -> service.initialize(new InitializeSkuStockCommand(Long.MAX_VALUE, 20, "INIT-MISSING")),
                ChannelInventoryErrorCode.INVENTORY_SKU_UNAVAILABLE);
        long disabledSkuId = createSku(0);
        assertError(() -> service.initialize(new InitializeSkuStockCommand(disabledSkuId, 20, "INIT-DISABLED")),
                ChannelInventoryErrorCode.INVENTORY_SKU_UNAVAILABLE);
    }

    @Test
    void allocatesReservesAndConfirmsExactlyOnce() {
        long skuId = initializedSku(20);

        var allocated = service.allocate(new AllocateChannelStockCommand(skuId, " mall ", 10, "ALLOC-1"));
        var reserved = service.reserve(new ReserveChannelStockCommand(skuId, "mall", 3, "RES-1"));
        var confirmed = service.confirm("RES-1");
        var repeated = service.confirm("RES-1");

        assertThat(allocated.channelCode()).isEqualTo("MALL");
        assertThat(allocated.allocatedStock()).isEqualTo(10);
        assertThat(reserved.availableStock()).isEqualTo(7);
        assertThat(reserved.reservedStock()).isEqualTo(3);
        assertThat(confirmed.reservedStock()).isZero();
        assertThat(confirmed.consumedStock()).isEqualTo(3);
        assertThat(confirmed.reservationStatus()).isEqualTo(InventoryReservationStatus.CONFIRMED);
        assertThat(repeated).isEqualTo(confirmed);
        assertThat(countLedger("RESERVE:RES-1")).isEqualTo(1);
        assertThat(countLedger("CONFIRM:RES-1")).isEqualTo(1);
        assertError(() -> service.release("RES-1"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);
    }

    @Test
    void releasesReservationExactlyOnceAndRejectsConfirmAfterRelease() {
        long skuId = initializedSku(20);
        service.allocate(new AllocateChannelStockCommand(skuId, "POINTS", 10, "ALLOC-POINTS"));
        service.reserve(new ReserveChannelStockCommand(skuId, "POINTS", 4, "RES-RELEASE"));

        var released = service.release("RES-RELEASE");
        var repeated = service.release("RES-RELEASE");

        assertThat(released.availableStock()).isEqualTo(10);
        assertThat(released.reservedStock()).isZero();
        assertThat(released.reservationStatus()).isEqualTo(InventoryReservationStatus.RELEASED);
        assertThat(repeated).isEqualTo(released);
        assertThat(countLedger("RELEASE:RES-RELEASE")).isEqualTo(1);
        assertError(() -> service.confirm("RES-RELEASE"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);
    }

    @Test
    void reversesConfirmedConsumptionExactlyOnce() {
        long skuId = initializedSku(20);
        service.allocate(new AllocateChannelStockCommand(skuId, "POINTS", 10, "ALLOC-RETURN"));
        service.reserve(new ReserveChannelStockCommand(skuId, "POINTS", 4, "RES-RETURN"));
        service.confirm("RES-RETURN");

        var reversed = service.reverseConfirmed("RES-RETURN");
        var repeated = service.reverseConfirmed("RES-RETURN");

        assertThat(reversed.availableStock()).isEqualTo(10);
        assertThat(reversed.reservedStock()).isZero();
        assertThat(reversed.consumedStock()).isZero();
        assertThat(reversed.reservationStatus()).isEqualTo(InventoryReservationStatus.REVERSED);
        assertThat(repeated).isEqualTo(reversed);
        assertThat(countLedger("RETURN:RES-RETURN")).isEqualTo(1);
    }

    @Test
    void reversesOnlyConfirmedReservationsAndKeepsTerminalStatesClosed() {
        long skuId = initializedSku(20);
        service.allocate(new AllocateChannelStockCommand(skuId, "POINTS", 10, "ALLOC-STATES"));

        service.reserve(new ReserveChannelStockCommand(skuId, "POINTS", 1, "RES-STILL-RESERVED"));
        assertError(() -> service.reverseConfirmed("RES-STILL-RESERVED"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);

        service.reserve(new ReserveChannelStockCommand(skuId, "POINTS", 1, "RES-ALREADY-RELEASED"));
        service.release("RES-ALREADY-RELEASED");
        assertError(() -> service.reverseConfirmed("RES-ALREADY-RELEASED"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);

        service.reserve(new ReserveChannelStockCommand(skuId, "POINTS", 1, "RES-ALREADY-REVERSED"));
        service.confirm("RES-ALREADY-REVERSED");
        service.reverseConfirmed("RES-ALREADY-REVERSED");
        assertError(() -> service.confirm("RES-ALREADY-REVERSED"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);
        assertError(() -> service.release("RES-ALREADY-REVERSED"),
                ChannelInventoryErrorCode.INVENTORY_STATE_CONFLICT);
    }

    @Test
    void returnsStableErrorsForInsufficientAndMissingInventory() {
        long skuId = initializedSku(5);

        assertError(() -> service.allocate(new AllocateChannelStockCommand(
                        skuId, "MALL", 6, "ALLOC-TOO-MUCH")),
                ChannelInventoryErrorCode.INVENTORY_INSUFFICIENT);
        service.allocate(new AllocateChannelStockCommand(skuId, "MALL", 3, "ALLOC-3"));
        assertError(() -> service.reserve(new ReserveChannelStockCommand(
                        skuId, "MALL", 4, "RES-TOO-MUCH")),
                ChannelInventoryErrorCode.INVENTORY_INSUFFICIENT);
        assertError(() -> service.get(skuId, "UNKNOWN"),
                ChannelInventoryErrorCode.INVENTORY_NOT_FOUND);
        assertError(() -> service.confirm("NO-RESERVATION"),
                ChannelInventoryErrorCode.INVENTORY_NOT_FOUND);
    }

    private long initializedSku(int totalStock) {
        long skuId = createSku(1);
        service.initialize(new InitializeSkuStockCommand(skuId, totalStock, "INIT-" + skuId));
        return skuId;
    }

    private long createSku(int status) {
        Product product = new Product();
        product.setProductCode("PROD-" + System.nanoTime());
        product.setProductName("库存测试商品");
        product.setProductType(ProductType.PHYSICAL);
        product.setStatus(1);
        productMapper.insert(product);

        ProductSku sku = new ProductSku();
        sku.setProductId(product.getId());
        sku.setSkuCode("SKU-" + System.nanoTime());
        sku.setSkuName("库存测试SKU");
        sku.setCashPriceCent(100L);
        sku.setCashEnabled(true);
        sku.setPointsEnabled(false);
        sku.setStatus(status);
        sku.setVersion(0);
        skuMapper.insert(sku);
        return sku.getId();
    }

    private int count(String table) {
        Integer count = jdbcTemplate.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
        return count == null ? 0 : count;
    }

    private int countLedger(String businessNo) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM inventory_ledger WHERE business_no = ?", Integer.class, businessNo);
        return count == null ? 0 : count;
    }

    private void assertError(Runnable action, ChannelInventoryErrorCode errorCode) {
        assertThatThrownBy(action::run)
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode()).isEqualTo(errorCode));
    }
}

package com.dongqh.luckyhub.domain.algorithm.lottery;

import org.junit.jupiter.api.Test;

import java.util.List;

import static com.dongqh.luckyhub.domain.algorithm.lottery.DrawCandidate.Type.NO_WIN;
import static com.dongqh.luckyhub.domain.algorithm.lottery.DrawCandidate.Type.PRIZE_CANDIDATE;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class WeightedDrawEngineTests {

    @Test
    void usesExactHalfOpenBoundariesAndIndependentNoWinInterval() {
        assertCandidate(selectAt(0, active(11, 101, 10), active(12, 102, 30)), 11, 101);
        assertCandidate(selectAt(9, active(11, 101, 10), active(12, 102, 30)), 11, 101);
        assertCandidate(selectAt(10, active(11, 101, 10), active(12, 102, 30)), 12, 102);
        assertCandidate(selectAt(39, active(11, 101, 10), active(12, 102, 30)), 12, 102);

        FixedRandomSource random = new FixedRandomSource(40);
        DrawCandidate result = new WeightedDrawEngineImpl(random)
                .select(List.of(active(11, 101, 10), active(12, 102, 30)), 60);

        assertThat(result.type()).isEqualTo(NO_WIN);
        assertThat(random.bound()).isEqualTo(100L);
    }

    @Test
    void zeroNoWinWeightLeavesTheLastPrizeBoundaryReachable() {
        FixedRandomSource random = new FixedRandomSource(39);

        DrawCandidate result = new WeightedDrawEngineImpl(random)
                .select(List.of(active(11, 101, 10), active(12, 102, 30)), 0);

        assertCandidate(result, 12, 102);
        assertThat(random.bound()).isEqualTo(40L);
    }

    @Test
    void disabledAndSoldOutIntervalsBecomeNoWinWithoutRedistribution() {
        List<PrizeWeightSnapshot> prizes = List.of(
                new PrizeWeightSnapshot(11, 101, 10, 5, false),
                new PrizeWeightSnapshot(12, 102, 30, 0, true),
                active(13, 103, 20)
        );

        assertThat(new WeightedDrawEngineImpl(new FixedRandomSource(0)).select(prizes, 40).type())
                .isEqualTo(NO_WIN);
        assertThat(new WeightedDrawEngineImpl(new FixedRandomSource(10)).select(prizes, 40).type())
                .isEqualTo(NO_WIN);
        assertCandidate(new WeightedDrawEngineImpl(new FixedRandomSource(40)).select(prizes, 40), 13, 103);
    }

    @Test
    void requiresValidPositiveTotalWeight() {
        WeightedDrawEngine engine = new WeightedDrawEngineImpl(new FixedRandomSource(0));

        assertThatThrownBy(() -> engine.select(List.of(), 0))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> engine.select(List.of(active(11, 101, 10)), -1))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> engine.select(
                List.of(new PrizeWeightSnapshot(11, 101, 0, 1, true)), 1))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void accumulatesBeyondIntegerRangeAndRejectsLongOverflow() {
        FixedRandomSource random = new FixedRandomSource(3_000_000_000L);
        DrawCandidate result = new WeightedDrawEngineImpl(random).select(List.of(
                active(11, 101, 2_000_000_000L),
                active(12, 102, 2_000_000_000L)
        ), 0);

        assertCandidate(result, 12, 102);
        assertThat(random.bound()).isEqualTo(4_000_000_000L);

        assertThatThrownBy(() -> new WeightedDrawEngineImpl(new FixedRandomSource(0)).select(List.of(
                active(11, 101, Long.MAX_VALUE),
                active(12, 102, 1)
        ), 0)).isInstanceOf(IllegalArgumentException.class);
    }

    private DrawCandidate selectAt(long value, PrizeWeightSnapshot... prizes) {
        return new WeightedDrawEngineImpl(new FixedRandomSource(value))
                .select(List.of(prizes), 60);
    }

    private PrizeWeightSnapshot active(long activityPrizeId, long prizeId, long weight) {
        return new PrizeWeightSnapshot(activityPrizeId, prizeId, weight, 1, true);
    }

    private void assertCandidate(DrawCandidate candidate, long activityPrizeId, long prizeId) {
        assertThat(candidate.type()).isEqualTo(PRIZE_CANDIDATE);
        assertThat(candidate.activityPrizeId()).isEqualTo(activityPrizeId);
        assertThat(candidate.prizeId()).isEqualTo(prizeId);
    }

    private static final class FixedRandomSource implements DrawRandomSource {
        private final long value;
        private long bound;

        private FixedRandomSource(long value) {
            this.value = value;
        }

        @Override
        public long nextLong(long bound) {
            this.bound = bound;
            return value;
        }

        private long bound() {
            return bound;
        }
    }
}

package com.dongqh.luckyhub.config.lottery;

import org.junit.jupiter.api.Test;
import org.redisson.api.RedissonClient;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;

import java.time.Duration;
import java.time.ZoneId;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest(properties = {
        "seata.enabled=false",
        "luckyhub.messaging.enabled=false"
})
class LotteryConfigurationTests {

    @Autowired
    private LotteryProperties properties;

    @Autowired
    private RedissonClient redissonClient;

    @Autowired
    private Environment environment;

    @Test
    void bindsSafeLotteryDefaults() {
        assertThat(properties.zoneId()).isEqualTo(ZoneId.of("Asia/Shanghai"));
        assertThat(properties.lockWait()).isEqualTo(Duration.ofSeconds(3));
        assertThat(properties.processingTimeout()).isEqualTo(Duration.ofMinutes(2));
        assertThat(properties.reconcileInterval()).isEqualTo(Duration.ofSeconds(30));
        assertThat(properties.reconcileInitialDelay()).isEqualTo(Duration.ofSeconds(60));
        assertThat(properties.reconcileBatchSize()).isEqualTo(100);
        assertThat(properties.outboxInterval()).isEqualTo(Duration.ofSeconds(5));
        assertThat(properties.outboxBatchSize()).isEqualTo(100);
        assertThat(redissonClient).isNotNull();
    }

    @Test
    void exposesRabbitMqReliabilitySettingsWithoutRedisStreamTransportSettings() {
        assertThat(environment.getProperty("spring.rabbitmq.virtual-host")).isEqualTo("/dongqh");
        assertThat(environment.getProperty("spring.rabbitmq.publisher-confirm-type"))
                .isEqualTo("correlated");
        assertThat(environment.getProperty("spring.rabbitmq.publisher-returns", Boolean.class))
                .isTrue();
        assertThat(environment.getProperty("spring.rabbitmq.template.mandatory", Boolean.class))
                .isTrue();
        assertThat(environment.getProperty("luckyhub.messaging.publisher-confirm-timeout", Duration.class))
                .isEqualTo(Duration.ofSeconds(5));
        assertThat(environment.getProperty("luckyhub.messaging.provider")).isNull();
        assertThat(environment.getProperty("luckyhub.messaging.lottery-stream")).isNull();
        assertThat(environment.getProperty("luckyhub.messaging.lottery-group")).isNull();
    }

    @Test
    void rejectsUnsafeMessagingAndOutboxSettings() {
        assertThatThrownBy(() -> new MessagingProperties(
                true, " ", Duration.ofSeconds(5), Duration.ofSeconds(30)))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new MessagingProperties(
                true, "consumer", Duration.ZERO, Duration.ofSeconds(30)))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new MessagingProperties(
                true, "consumer", Duration.ofSeconds(5), Duration.ZERO))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ofMinutes(2), Duration.ofSeconds(30), Duration.ofSeconds(1), 100,
                Duration.ofSeconds(5), 0))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ZERO, Duration.ZERO, 100))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ofSeconds(1),
                Duration.ofSeconds(-1), 100)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ofSeconds(1),
                Duration.ZERO, 0)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ZERO, Duration.ofSeconds(30), Duration.ZERO, 100,
                Duration.ofSeconds(5), 100))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private LotteryProperties propertiesWithReconciliation(
            Duration interval, Duration initialDelay, int batchSize) {
        return new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ofMinutes(2), interval, initialDelay, batchSize,
                Duration.ofSeconds(5), 100);
    }
}

