import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(properties = {
        "luckyhub.lottery.reconciliation-enabled=false",
        "spring.data.redis.database=15"
})
class LotteryReconciliationServiceTests {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final long USER_ID = 880013L;
    private static final long ACTIVITY_ID = 990013L;

    @Autowired private LotteryReconciliationService service;
    @Autowired private DrawOrderLifecycleService lifecycleService;
    @Autowired private LotteryDrawOrderMapper orderMapper;
    @Autowired private DrawQuotaService quotaService;
    @Autowired private DrawLockService lockService;
    @Autowired private StringRedisTemplate redisTemplate;
    @Autowired private JdbcTemplate jdbcTemplate;
    private final Set<String> requestIds = new LinkedHashSet<>();
    private final Set<String> quotaKeys = new LinkedHashSet<>();
    private final Map<String, LocalDate> drawDates = new LinkedHashMap<>();

    @AfterEach
    void cleanUp() {
        for (String requestId : requestIds) {
            jdbcTemplate.update("DELETE FROM message_outbox WHERE aggregate_id IN "
                    + "(SELECT CAST(id AS CHAR) FROM lottery_draw_order WHERE request_id = ?)", requestId);
            jdbcTemplate.update("DELETE FROM lottery_draw_order WHERE request_id = ?", requestId);
            redisTemplate.delete(DrawQuotaKeys.reservation(requestId));
            redisTemplate.opsForZSet().remove(DrawQuotaKeys.reservationTimeouts(), requestId);
        }
        redisTemplate.delete(quotaKeys);
        quotaKeys.clear();
        drawDates.clear();
        requestIds.clear();
    }

    @Test
    void confirmsSuccessfulOrderAndRemovesTimeoutMember() {
        String requestId = reserveDue();
        LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now().minusMinutes(3));
        jdbcTemplate.update("UPDATE lottery_draw_order SET status = 'SUCCESS' WHERE id = ?", order.getId());

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(status(requestId)).isEqualTo("CONFIRMED");
        assertThat(score(requestId)).isNull();
        assertThat(result.confirmed()).isEqualTo(1);
    }

    @Test
    void releasesFailedAndMissingOrdersWithoutStoppingTheBatch() {
        String failed = reserveDue();
        LotteryDrawOrder failedOrder = createOrder(failed, LocalDateTime.now().minusMinutes(3));
        jdbcTemplate.update("UPDATE lottery_draw_order SET status = 'FAILED' WHERE id = ?", failedOrder.getId());
        String missing = reserveDue();

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(status(failed)).isEqualTo("RELEASED");
        assertThat(status(missing)).isEqualTo("RELEASED");
        assertThat(result.released()).isEqualTo(2);
    }

    @Test
    void freshProcessingOrderIsLeftProcessingAndRescheduledToItsRealDeadline() {
        String requestId = reserveDue();
        LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now());

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(orderMapper.selectById(order.getId()).getStatus()).isEqualTo(DrawOrderStatus.PROCESSING);
        assertThat(status(requestId)).isEqualTo("RESERVED");
        assertThat(score(requestId)).isGreaterThan(Instant.now().toEpochMilli());
        assertThat(result.deferred()).isEqualTo(1);
    }

    @Test
    void expiredProcessingOrderBecomesFailedAndAppendsReleaseEventAtomically() {
        String requestId = reserveDue();
        LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now().minusMinutes(3));

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        LotteryDrawOrder stored = orderMapper.selectById(order.getId());
        assertThat(stored.getStatus()).isEqualTo(DrawOrderStatus.FAILED);
        assertThat(stored.getFailReason()).isEqualTo("PROCESSING_TIMEOUT");
        assertThat(jdbcTemplate.queryForObject("""
                SELECT COUNT(*) FROM message_outbox
                WHERE aggregate_id = ? AND event_type = 'DRAW_RELEASE_REQUESTED'
                """, Integer.class, Long.toString(order.getId()))).isOne();
        assertThat(status(requestId)).isEqualTo("RESERVED");
        assertThat(result.timedOut()).isEqualTo(1);
    }

    @Test
    void concurrentSuccessWinnerIsReloadedAndConfirmedInsteadOfOverwritten() throws Exception {
        String requestId = reserveDue();
        LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now().minusMinutes(3));
        CountDownLatch reconciliationReachedTransition = new CountDownLatch(1);
        CountDownLatch successCommitted = new CountDownLatch(1);
        DrawOrderLifecycleService controlledLifecycle = new DrawOrderLifecycleService() {
            @Override public LotteryDrawOrder createProcessing(NewDrawOrder command) { throw new UnsupportedOperationException(); }
            @Override public void markFailed(long orderId, String safeReason) { throw new UnsupportedOperationException(); }
            @Override public void markFailedAndRequestRelease(LotteryDrawOrder candidate, String reason,
                                                               LocalDateTime occurredAt) {
                reconciliationReachedTransition.countDown();
                await(successCommitted);
                lifecycleService.markFailedAndRequestRelease(candidate, reason, occurredAt);
            }
        };
        LotteryReconciliationService controlled = new LotteryReconciliationServiceImpl(
                redisTemplate, orderMapper, controlledLifecycle, quotaService, lockService,
                Duration.ofMinutes(2), ZONE, 100);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<ReconciliationResult> reconciliation = executor.submit(
                    () -> controlled.reconcileExpiredReservations(Instant.now()));
            assertThat(reconciliationReachedTransition.await(5, TimeUnit.SECONDS)).isTrue();
            Future<Integer> success = executor.submit(() -> {
                int updated = orderMapper.markSuccessIfProcessing(order.getId(), LocalDateTime.now());
                successCommitted.countDown();
                return updated;
            });

            assertThat(success.get(5, TimeUnit.SECONDS)).isOne();
            ReconciliationResult result = reconciliation.get(5, TimeUnit.SECONDS);
            assertThat(orderMapper.selectById(order.getId()).getStatus()).isEqualTo(DrawOrderStatus.SUCCESS);
            assertThat(status(requestId)).isEqualTo("CONFIRMED");
            assertThat(result.confirmed()).isOne();
            assertThat(jdbcTemplate.queryForObject(
                    "SELECT COUNT(*) FROM message_outbox WHERE aggregate_id = ?",
                    Integer.class, Long.toString(order.getId()))).isZero();
        } finally {
            successCommitted.countDown();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    @Test
    void readsOnlyConfiguredBatchFromTimeoutSortedSet() {
        String first = reserveDue();
        String second = reserveDue();
        String third = reserveDue();
        LotteryReconciliationService bounded = new LotteryReconciliationServiceImpl(
                redisTemplate, orderMapper, lifecycleService, quotaService, lockService,
                Duration.ofMinutes(2), ZONE, 2);

        ReconciliationResult result = bounded.reconcileExpiredReservations(Instant.now());

        assertThat(result.scanned()).isEqualTo(2);
        assertThat(java.util.List.of(status(first), status(second), status(third)))
                .containsExactlyInAnyOrder("RESERVED", "RELEASED", "RELEASED");
        assertThat(requestIds.stream().filter(id -> score(id) != null)).hasSize(1);
    }

    @Test
    void oneDamagedReservationDoesNotPreventTheNextRequestFromBeingReleased() {
        String damaged = reserveDue();
        String healthy = reserveDue();
        redisTemplate.opsForHash().delete(DrawQuotaKeys.reservation(damaged), "activityId");
        redisTemplate.opsForZSet().add(DrawQuotaKeys.reservationTimeouts(), damaged,
                Instant.now().minusSeconds(2).toEpochMilli());

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(result.failed()).isOne();
        assertThat(result.released()).isOne();
        assertThat(status(damaged)).isEqualTo("RESERVED");
        assertThat(score(damaged)).isGreaterThan(Instant.now().toEpochMilli());
        assertThat(status(healthy)).isEqualTo("RELEASED");
    }

    @Test
    void concurrentWorkersConfirmTheSameReservationIdempotently() throws Exception {
        String requestId = reserveDue();
        LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now().minusMinutes(3));
        jdbcTemplate.update("UPDATE lottery_draw_order SET status = 'SUCCESS' WHERE id = ?", order.getId());
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            CountDownLatch start = new CountDownLatch(1);
            Future<ReconciliationResult> first = executor.submit(() -> {
                await(start);
                return service.reconcileExpiredReservations(Instant.now());
            });
            Future<ReconciliationResult> second = executor.submit(() -> {
                await(start);
                return service.reconcileExpiredReservations(Instant.now());
            });
            start.countDown();
            first.get(5, TimeUnit.SECONDS);
            second.get(5, TimeUnit.SECONDS);

            assertThat(status(requestId)).isEqualTo("CONFIRMED");
            assertThat(score(requestId)).isNull();
            assertThat(quotaValue(requestId)).isEqualTo("1");
        } finally {
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    @Test
    void reconciliationWaitsForTheCreatorLockAndCannotReleaseBetweenReserveAndOrderCreation()
            throws Exception {
        String requestId = newRequestId();
        CountDownLatch reservedWhileLocked = new CountDownLatch(1);
        CountDownLatch reconciliationRequestedLock = new CountDownLatch(1);
        CountDownLatch allowCreatorToFinish = new CountDownLatch(1);
        DrawLockService observableLock = new DrawLockService() {
            @Override
            public <T> T execute(long activityId, long userId, java.util.function.Supplier<T> action) {
                reconciliationRequestedLock.countDown();
                return lockService.execute(activityId, userId, action);
            }
        };
        LotteryReconciliationService controlled = new LotteryReconciliationServiceImpl(
                redisTemplate, orderMapper, lifecycleService, quotaService, observableLock,
                Duration.ofMillis(50), ZONE, 100);
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<?> creator = executor.submit(() -> lockService.execute(ACTIVITY_ID, USER_ID, () -> {
                reserveExistingRequestDue(requestId);
                reservedWhileLocked.countDown();
                await(allowCreatorToFinish);
                LotteryDrawOrder order = createOrder(requestId, LocalDateTime.now());
                assertThat(orderMapper.markSuccessIfProcessing(order.getId(), LocalDateTime.now())).isOne();
                return null;
            }));
            assertThat(reservedWhileLocked.await(5, TimeUnit.SECONDS)).isTrue();

            Future<ReconciliationResult> reconciliation = executor.submit(
                    () -> controlled.reconcileExpiredReservations(Instant.now()));
            assertThat(reconciliationRequestedLock.await(5, TimeUnit.SECONDS)).isTrue();
            Thread.sleep(100);
            assertThat(status(requestId)).isEqualTo("RESERVED");
            allowCreatorToFinish.countDown();

            creator.get(5, TimeUnit.SECONDS);
            assertThat(reconciliation.get(5, TimeUnit.SECONDS).confirmed()).isOne();
            assertThat(status(requestId)).isEqualTo("CONFIRMED");
        } finally {
            allowCreatorToFinish.countDown();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    @Test
    void reservationWhoseCreatorCrashesAfterUnlockIsReleased() {
        String requestId = newRequestId();
        lockService.execute(ACTIVITY_ID, USER_ID, () -> {
            reserveExistingRequestDue(requestId);
            return null;
        });

        service.reconcileExpiredReservations(Instant.now());

        assertThat(status(requestId)).isEqualTo("RELEASED");
    }

    @Test
    void reservationAndOrderIdentityMismatchIsDeferredWithoutChangingQuota() {
        String requestId = reserveDue();
        createOrder(requestId, LocalDateTime.now().minusMinutes(3));
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(requestId), "drawCount", "10");

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(result.failed()).isOne();
        assertThat(status(requestId)).isEqualTo("RESERVED");
        assertThat(quotaValue(requestId)).isEqualTo("1");
        assertThat(score(requestId)).isGreaterThan(Instant.now().toEpochMilli());
    }

    @Test
    void malformedReservedIdentityIsQuarantinedButMalformedTerminalIdentityOnlyCleansTimeout() {
        String reserved = reserveDue();
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(reserved), "drawDate", "bad-date");
        String terminal = reserveDue();
        quotaService.confirm(terminal);
        redisTemplate.opsForHash().delete(DrawQuotaKeys.reservation(terminal), "userId");
        redisTemplate.opsForZSet().add(DrawQuotaKeys.reservationTimeouts(), terminal,
                Instant.now().minusSeconds(1).toEpochMilli());

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(result.failed()).isOne();
        assertThat(status(reserved)).isEqualTo("RESERVED");
        assertThat(score(reserved)).isGreaterThan(Instant.now().toEpochMilli());
        assertThat(status(terminal)).isEqualTo("CONFIRMED");
        assertThat(score(terminal)).isNull();
        assertThat(quotaValue(terminal)).isEqualTo("2");
    }

    @Test
    void everyMalformedReservedIdentityFieldIsDeferredWithoutTouchingQuota() {
        String badRequest = reserveDue();
        redisTemplate.opsForHash().put(
                DrawQuotaKeys.reservation(badRequest), "requestId", UUID.randomUUID().toString());
        String badActivity = reserveDue();
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(badActivity), "activityId", "0");
        String badUser = reserveDue();
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(badUser), "userId", "not-a-number");
        String badCount = reserveDue();
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(badCount), "drawCount", "2");
        String badDate = reserveDue();
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(badDate), "drawDate", "2026-99-99");

        ReconciliationResult result = service.reconcileExpiredReservations(Instant.now());

        assertThat(result.failed()).isEqualTo(5);
        assertThat(java.util.List.of(badRequest, badActivity, badUser, badCount, badDate))
                .allSatisfy(requestId -> {
                    assertThat(status(requestId)).isEqualTo("RESERVED");
                    assertThat(score(requestId)).isGreaterThan(Instant.now().toEpochMilli());
                });
        assertThat(quotaValue(badDate)).isEqualTo("5");
    }

    private String reserveDue() {
        String requestId = newRequestId();
        reserveExistingRequestDue(requestId);
        return requestId;
    }

    private String newRequestId() {
        String requestId = UUID.randomUUID().toString();
        requestIds.add(requestId);
        return requestId;
    }

    private void reserveExistingRequestDue(String requestId) {
        var reservation = quotaService.reserve(
                new QuotaReservationRequest(requestId, ACTIVITY_ID, USER_ID, 1, 100));
        drawDates.put(requestId, reservation.drawDate());
        quotaKeys.add(DrawQuotaKeys.quota(ACTIVITY_ID, USER_ID, reservation.drawDate()));
        redisTemplate.opsForZSet().add(DrawQuotaKeys.reservationTimeouts(), requestId,
                Instant.now().minusSeconds(1).toEpochMilli());
    }

    private LotteryDrawOrder createOrder(String requestId, LocalDateTime createdAt) {
        LotteryDrawOrder order = lifecycleService.createProcessing(new NewDrawOrder(
                requestId, USER_ID, ACTIVITY_ID, 1, drawDates.get(requestId)));
        jdbcTemplate.update("UPDATE lottery_draw_order SET created_at = ? WHERE id = ?", createdAt, order.getId());
        return orderMapper.selectById(order.getId());
    }

    private String status(String requestId) {
        Object value = redisTemplate.opsForHash().get(DrawQuotaKeys.reservation(requestId), "status");
        return value == null ? null : value.toString();
    }

    private Double score(String requestId) {
        return redisTemplate.opsForZSet().score(DrawQuotaKeys.reservationTimeouts(), requestId);
    }

    private String quotaValue(String requestId) {
        return redisTemplate.opsForValue().get(
                DrawQuotaKeys.quota(ACTIVITY_ID, USER_ID, drawDates.get(requestId)));
    }

    private static void await(CountDownLatch latch) {
        try {
            if (!latch.await(5, TimeUnit.SECONDS)) {
                throw new AssertionError("timed out waiting for concurrent transition");
            }
        } catch (InterruptedException error) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(error);
        }
    }
}

package com.dongqh.luckyhub.service.lottery;

import com.dongqh.luckyhub.domain.context.auth.LoginContext;
import com.dongqh.luckyhub.domain.model.auth.LoginPrincipal;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.enums.drawchance.DrawChanceReservationStatus;
import com.dongqh.luckyhub.domain.model.drawchance.DrawChanceReservationResult;
import com.dongqh.luckyhub.service.drawchance.DrawChanceService;
import com.dongqh.luckyhub.domain.dto.lottery.DrawCommand;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawOrder;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.DrawResultType;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.domain.lock.lottery.DrawLockService;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawOrderMapper;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.domain.model.lottery.DrawExecutionResult;
import com.dongqh.luckyhub.domain.model.lottery.DrawPrizeSnapshot;
import com.dongqh.luckyhub.domain.model.lottery.DrawResultItem;
import com.dongqh.luckyhub.domain.quota.lottery.DrawQuotaService;
import com.dongqh.luckyhub.domain.quota.lottery.QuotaReservationResult;
import com.dongqh.luckyhub.domain.quota.lottery.ReservationStatus;
import com.dongqh.luckyhub.service.lottery.impl.LotteryServiceImpl;
import com.dongqh.luckyhub.domain.vo.lottery.DrawOrderView;
import com.dongqh.luckyhub.enums.prize.PrizeType;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.InOrder;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class LotteryServiceTests {

    private final LotteryDrawOrderMapper orderMapper = mock(LotteryDrawOrderMapper.class);
    private final LotteryDrawRecordMapper recordMapper = mock(LotteryDrawRecordMapper.class);
    private final DrawEligibilityService eligibility = mock(DrawEligibilityService.class);
    private final DrawLockService lock = mock(DrawLockService.class);
    private final DrawQuotaService quota = mock(DrawQuotaService.class);
    private final DrawOrderLifecycleService lifecycle = mock(DrawOrderLifecycleService.class);
    private final DrawTransactionService transaction = mock(DrawTransactionService.class);
    private final DrawChanceService drawChances = mock(DrawChanceService.class);
    private final LotteryService service = new LotteryServiceImpl(
            orderMapper, recordMapper, eligibility, lock, quota, lifecycle, transaction, drawChances);

    private final String requestId = UUID.randomUUID().toString();
    private final DrawCommand command = new DrawCommand(requestId, 20L, 1);
    private final LocalDate drawDate = LocalDate.of(2026, 7, 31);
    private final LocalDateTime now = LocalDateTime.of(2026, 7, 31, 12, 0);

    @BeforeEach
    void setUp() {
        LoginContext.set(new LoginPrincipal(10L, "user", "session"));
        when(lock.execute(anyLong(), anyLong(), any())).thenAnswer(invocation ->
                invocation.<java.util.function.Supplier<?>>getArgument(2).get());
        when(eligibility.load(20L)).thenReturn(new DrawEligibilityService.EligibilitySnapshot(
                20L, 5, 25, List.of(prize()), now));
        when(quota.reserve(any())).thenReturn(new QuotaReservationResult(
                requestId, ReservationStatus.RESERVED, drawDate, 1, false));
        when(drawChances.reserve(any())).thenReturn(new DrawChanceReservationResult(
                requestId, 20L, 10L, 1, drawDate, 0, 0,
                DrawChanceReservationStatus.RESERVED, false));
        when(lifecycle.createProcessing(any())).thenReturn(order(99L, DrawOrderStatus.PROCESSING));
        when(transaction.execute(any())).thenReturn(new DrawExecutionResult(
                99L, requestId, DrawOrderStatus.SUCCESS, now,
                List.of(new DrawResultItem(101L, 1, DrawResultType.WIN, 30L,
                        "一等奖", PrizeType.COUPON, "https://img", 201L))));
    }

    @AfterEach
    void clearLogin() {
        LoginContext.clear();
    }

    @Test
    void orchestratesInRequiredOrderAndReturnsExactSynchronousResult() {
        DrawOrderView result = service.draw(command);

        assertThat(result.requestId()).isEqualTo(requestId);
        assertThat(result.status()).isEqualTo(DrawOrderStatus.SUCCESS);
        assertThat(result.results()).singleElement().satisfies(item -> {
            assertThat(item.sequenceNo()).isOne();
            assertThat(item.resultType()).isEqualTo(DrawResultType.WIN);
            assertThat(item.prizeName()).isEqualTo("一等奖");
            assertThat(item.benefitId()).isEqualTo(201L);
        });
        InOrder ordered = inOrder(orderMapper, eligibility, lock, drawChances, quota, lifecycle, transaction);
        ordered.verify(orderMapper).selectByRequestId(requestId);
        ordered.verify(eligibility).load(20L);
        ordered.verify(lock).execute(eq(20L), eq(10L), any());
        ordered.verify(orderMapper).selectByRequestId(requestId);
        ordered.verify(drawChances).reserve(argThat(r -> r.drawDate().equals(drawDate)));
        ordered.verify(quota).reserve(argThat(r -> r.userId() == 10L && r.dailyLimit() == 5));
        ordered.verify(lifecycle).createProcessing(argThat(o -> o.drawDate().equals(drawDate)));
        ordered.verify(transaction).execute(argThat(c -> c.prizes().size() == 1
                && c.noWinWeight() == 25 && c.drawTime().equals(now)));
        verify(eligibility, times(1)).load(20L);
    }

    @Test
    void cumulativeRewardedChancesIncreaseRedisLimitAndRedisFailureReleasesReservation() {
        when(drawChances.reserve(any())).thenReturn(new DrawChanceReservationResult(
                requestId, 20L, 10L, 1, drawDate, 1, 2,
                DrawChanceReservationStatus.RESERVED, false));

        service.draw(command);
        verify(quota).reserve(argThat(request -> request.dailyLimit() == 7
                && request.drawDate().equals(drawDate)));

        reset(quota);
        when(quota.reserve(any())).thenThrow(new BusinessException(LotteryErrorCode.DRAW_QUOTA_UNAVAILABLE));
        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_QUOTA_UNAVAILABLE);
        verify(drawChances).release(requestId);
    }

    @Test
    void returnsStoredSuccessBeforeEligibilityEvenAcrossPolicyOrDateChanges() {
        LotteryDrawOrder success = order(7L, DrawOrderStatus.SUCCESS);
        success.setDrawDate(LocalDate.of(2026, 7, 30));
        success.setCompletedAt(now.minusDays(1));
        when(orderMapper.selectByRequestId(requestId)).thenReturn(success);
        LotteryDrawRecord record = new LotteryDrawRecord();
        record.setId(8L); record.setSequenceNo(1); record.setResultType(DrawResultType.NO_WIN);
        when(recordMapper.selectByOrderId(7L)).thenReturn(List.of(record));

        DrawOrderView result = service.draw(command);

        assertThat(result.drawDate()).isEqualTo(LocalDate.of(2026, 7, 30));
        assertThat(result.results()).singleElement().extracting("resultType")
                .isEqualTo(DrawResultType.NO_WIN);
        verifyNoInteractions(eligibility, lock, quota, lifecycle, transaction);
    }

    @Test
    void rejectsInvalidUuidAndUnsupportedDrawCountBeforeDependencies() {
        assertError(() -> service.draw(new DrawCommand(" ", 20L, 1)), LotteryErrorCode.DRAW_PARAMETER_INVALID);
        assertError(() -> service.draw(new DrawCommand("hmall-1788418028039-12345", 20L, 1)),
                LotteryErrorCode.DRAW_PARAMETER_INVALID);
        assertError(() -> service.draw(new DrawCommand(UUID.randomUUID().toString(), 20L, 2)), LotteryErrorCode.DRAW_PARAMETER_INVALID);
        verifyNoInteractions(orderMapper, eligibility, lock, quota, lifecycle, transaction);
    }

    @Test
    void existingProcessingFailedAndConflictingIdentityAreTerminal() {
        when(orderMapper.selectByRequestId(requestId)).thenReturn(order(1L, DrawOrderStatus.PROCESSING));
        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_PROCESSING);

        when(orderMapper.selectByRequestId(requestId)).thenReturn(order(1L, DrawOrderStatus.FAILED));
        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_FAILED);

        LotteryDrawOrder conflict = order(1L, DrawOrderStatus.SUCCESS);
        conflict.setDrawCount(10);
        when(orderMapper.selectByRequestId(requestId)).thenReturn(conflict);
        assertError(() -> service.draw(command), LotteryErrorCode.IDEMPOTENCY_CONFLICT);
    }

    @Test
    void secondIdempotencyCheckPreventsQuotaReservation() {
        when(orderMapper.selectByRequestId(requestId))
                .thenReturn(null, order(1L, DrawOrderStatus.PROCESSING));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_PROCESSING);
        verifyNoInteractions(quota, lifecycle, transaction);
    }

    @Test
    void successDiscoveredBySecondIdempotencyCheckReturnsStoredResult() {
        LotteryDrawOrder success = order(1L, DrawOrderStatus.SUCCESS);
        when(orderMapper.selectByRequestId(requestId)).thenReturn(null, success);
        LotteryDrawRecord record = new LotteryDrawRecord();
        record.setId(2L); record.setSequenceNo(1); record.setResultType(DrawResultType.NO_WIN);
        when(recordMapper.selectByOrderId(1L)).thenReturn(List.of(record));

        DrawOrderView result = service.draw(command);

        assertThat(result.orderId()).isOne();
        assertThat(result.results()).hasSize(1);
        verifyNoInteractions(quota, lifecycle, transaction);
    }

    @Test
    void failureAfterOrderCreationMarksFailedAndAppendsReleaseInNewTransaction() {
        when(transaction.execute(any())).thenThrow(new IllegalStateException("SQL password should not leak"));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_TRANSACTION_FAILED);

        verify(lifecycle).markFailedAndRequestRelease(
                argThat(o -> o.getId() == 99L), eq("DRAW_TRANSACTION_FAILED"), eq(now));
    }

    @Test
    void mysqlFailureBeforeOrderExistsImmediatelyReleasesBothReservations() {
        when(lifecycle.createProcessing(any())).thenThrow(new IllegalStateException("mysql down"));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_TRANSACTION_FAILED);

        verify(lifecycle, never()).markFailedAndRequestRelease(any(), anyString(), any());
        verify(quota).release(requestId);
        verify(drawChances).release(requestId);
    }

    @Test
    void reservationReleasedByReconciliationBeforeExecutionFailsCreatedOrder() {
        when(drawChances.reserve(any())).thenReturn(
                new DrawChanceReservationResult(requestId, 20L, 10L, 1, drawDate, 1, 1,
                        DrawChanceReservationStatus.RESERVED, false),
                new DrawChanceReservationResult(requestId, 20L, 10L, 1, drawDate, 1, 0,
                        DrawChanceReservationStatus.RELEASED, true));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_FAILED);

        verify(drawChances, times(2)).reserve(any());
        verifyNoInteractions(transaction);
        verify(lifecycle).markFailedAndRequestRelease(
                argThat(o -> o.getId() == 99L), eq("DRAW_TRANSACTION_FAILED"), eq(now));
    }

    @Test
    void releasedReservationWithoutMysqlOrderCannotCreateOrExecuteAgain() {
        when(quota.reserve(any())).thenReturn(new QuotaReservationResult(
                requestId, ReservationStatus.RELEASED, drawDate.minusDays(1), 1, true));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_FAILED);

        verify(lifecycle, never()).createProcessing(any());
        verifyNoInteractions(transaction);
    }

    @Test
    void confirmedReservationWithoutMysqlOrderCannotCreateOrExecuteAgain() {
        when(quota.reserve(any())).thenReturn(new QuotaReservationResult(
                requestId, ReservationStatus.CONFIRMED, drawDate, 1, true));

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_ORDER_FAILED);

        verify(lifecycle, never()).createProcessing(any());
        verifyNoInteractions(transaction);
    }

    @Test
    void compensationLoggingFailureDoesNotReplaceOriginalSafeBusinessError() {
        when(transaction.execute(any())).thenThrow(new BusinessException(LotteryErrorCode.DRAW_WEIGHT_INVALID));
        doThrow(new IllegalStateException("outbox down")).when(lifecycle)
                .markFailedAndRequestRelease(any(), anyString(), any());

        assertError(() -> service.draw(command), LotteryErrorCode.DRAW_WEIGHT_INVALID);
    }

    @Test
    void getByRequestIdEnforcesJwtOwnership() {
        LotteryDrawOrder other = order(1L, DrawOrderStatus.SUCCESS);
        other.setUserId(999L);
        when(orderMapper.selectByRequestId(requestId)).thenReturn(other);

        assertError(() -> service.getByRequestId(requestId), LotteryErrorCode.DRAW_ACCESS_DENIED);
    }

    private LotteryDrawOrder order(long id, DrawOrderStatus status) {
        LotteryDrawOrder order = new LotteryDrawOrder();
        order.setId(id); order.setRequestId(requestId); order.setUserId(10L); order.setActivityId(20L);
        order.setDrawCount(1); order.setDrawDate(drawDate); order.setStatus(status); order.setCompletedAt(now);
        return order;
    }

    private DrawPrizeSnapshot prize() {
        return new DrawPrizeSnapshot(40L, 30L, "一等奖", PrizeType.COUPON,
                "https://img", 75, 10, true);
    }

    private void assertError(org.assertj.core.api.ThrowableAssert.ThrowingCallable action,
                             LotteryErrorCode code) {
        assertThatThrownBy(action).isInstanceOfSatisfying(BusinessException.class,
                error -> assertThat(error.getErrorCode()).isEqualTo(code));
    }
}

