package com.dongqh.luckyhub.domain.image.prize;

import com.dongqh.luckyhub.config.prize.OssProperties;
import com.dongqh.luckyhub.domain.storage.prize.ObjectStorageGateway;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockMultipartFile;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

class PrizeImageServiceTests {

    @Test
    void uploadsValidatedImageAndReturnsPublicUrl() {
        CapturingGateway gateway = new CapturingGateway();
        OssProperties properties = new OssProperties(
                true,
                "cn-hangzhou",
                "https://oss-cn-hangzhou.aliyuncs.com",
                "luckyhub-prizes",
                "key-id",
                "key-secret",
                "https://cdn.example.com/prizes/"
        );
        PrizeImageService service = new PrizeImageService(
                new PrizeImageValidator(),
                gateway,
                properties,
                Clock.fixed(Instant.parse("2026-07-27T12:00:00Z"), ZoneOffset.UTC),
                () -> UUID.fromString("123e4567-e89b-12d3-a456-426614174000")
        );

        var result = service.upload(new MockMultipartFile(
                "file", "prize.png", "image/png",
                new byte[]{(byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}
        ));

        assertThat(result.objectKey())
                .isEqualTo("prizes/2026/07/123e4567-e89b-12d3-a456-426614174000.png");
        assertThat(result.url())
                .isEqualTo("https://cdn.example.com/prizes/prizes/2026/07/123e4567-e89b-12d3-a456-426614174000.png");
        assertThat(gateway.objectKey).isEqualTo(result.objectKey());
        assertThat(gateway.contentType).isEqualTo("image/png");
    }

    private static final class CapturingGateway implements ObjectStorageGateway {
        private String objectKey;
        private String contentType;

        @Override
        public void put(String objectKey, byte[] content, String contentType) {
            this.objectKey = objectKey;
            this.contentType = contentType;
        }
    }
}

package com.dongqh.luckyhub.domain.image.prize;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.enums.prize.PrizeErrorCode;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockMultipartFile;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class PrizeImageValidatorTests {

    private final PrizeImageValidator validator = new PrizeImageValidator();

    @Test
    void rejectsEmptyImage() {
        assertError(new MockMultipartFile("file", new byte[0]), PrizeErrorCode.IMAGE_EMPTY);
    }

    @Test
    void rejectsImageLargerThanFiveMib() {
        assertError(
                new MockMultipartFile("file", "large.png", "image/png", new byte[5 * 1024 * 1024 + 1]),
                PrizeErrorCode.IMAGE_TOO_LARGE
        );
    }

    @Test
    void rejectsUnsupportedOrMismatchedContent() {
        assertError(
                new MockMultipartFile("file", "x.gif", "image/gif", new byte[]{'G', 'I', 'F'}),
                PrizeErrorCode.IMAGE_TYPE_UNSUPPORTED
        );
        assertError(
                new MockMultipartFile("file", "x.jpg", "image/jpeg",
                        new byte[]{(byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}),
                PrizeErrorCode.IMAGE_TYPE_UNSUPPORTED
        );
    }

    @Test
    void recognizesJpegPngAndWebpMagicBytes() {
        ValidatedImage jpeg = validator.validate(new MockMultipartFile(
                "file", "x.jpg", "image/jpeg", new byte[]{(byte) 0xFF, (byte) 0xD8, (byte) 0xFF, 0x01}
        ));
        ValidatedImage png = validator.validate(new MockMultipartFile(
                "file", "x.png", "image/png",
                new byte[]{(byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}
        ));
        ValidatedImage webp = validator.validate(new MockMultipartFile(
                "file", "x.webp", "image/webp",
                new byte[]{'R', 'I', 'F', 'F', 0, 0, 0, 0, 'W', 'E', 'B', 'P'}
        ));

        assertThat(jpeg.extension()).isEqualTo("jpg");
        assertThat(png.extension()).isEqualTo("png");
        assertThat(webp.extension()).isEqualTo("webp");
    }

    private void assertError(MockMultipartFile file, PrizeErrorCode errorCode) {
        assertThatThrownBy(() -> validator.validate(file))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode()).isEqualTo(errorCode));
    }
}

