import com.dongqh.luckyhub.service.reward.RewardDefinitionService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

import java.util.List;
import java.time.LocalDateTime;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.when;

@SpringBootTest
class RewardDefinitionServiceTests {

    @Autowired
    private RewardDefinitionService service;

    @Autowired
    private RewardDefinitionMapper rewardMapper;

    @Autowired
    private ProductMapper productMapper;

    @Autowired
    private ProductSkuMapper skuMapper;
    @Autowired private CouponTemplateMapper couponMapper;
    @Autowired private MembershipProductMapper membershipMapper;
    @MockitoBean private HmallCatalogClient hmallCatalog;

    @BeforeEach
    void cleanTables() {
        rewardMapper.delete(new LambdaQueryWrapper<>());
        couponMapper.delete(new LambdaQueryWrapper<>());
        membershipMapper.delete(new LambdaQueryWrapper<>());
        skuMapper.delete(new LambdaQueryWrapper<>());
        productMapper.delete(new LambdaQueryWrapper<>());
    }

    @Test
    void createsAllFiveRewardTypesAndNormalizesJson() {
        long skuId = createSku(1);
        long couponId = createCoupon();
        long membershipId = createMembership();
        List<CreateRewardDefinitionCommand> commands = List.of(
                command("PRODUCT-1", RewardType.PRODUCT, skuId, " { \"source\" : \"mall\" } "),
                command("COUPON-1", RewardType.COUPON, couponId, null),
                command("POINTS-1", RewardType.POINTS, null, "   "),
                command("MEMBER-1", RewardType.MEMBERSHIP, membershipId, null),
                command("DRAW-1", RewardType.DRAW_CHANCE, null, null)
        );

        var views = commands.stream().map(service::create).toList();

        assertThat(views).extracting(view -> view.rewardType())
                .containsExactly(RewardType.PRODUCT, RewardType.COUPON, RewardType.POINTS,
                        RewardType.MEMBERSHIP, RewardType.DRAW_CHANCE);
        assertThat(views.get(0).configSnapshot()).isEqualTo("{\"source\":\"mall\"}");
        assertThat(views.get(2).configSnapshot()).isNull();
        assertThat(service.get(views.get(0).id()).rewardCode()).isEqualTo("PRODUCT-1");
        assertThat(rewardMapper.selectCount(new LambdaQueryWrapper<>())).isEqualTo(5);
    }

    @Test
    void rejectsMissingOrUnexpectedTargets() {
        for (RewardType type : List.of(RewardType.PRODUCT, RewardType.COUPON, RewardType.MEMBERSHIP)) {
            assertTargetInvalid(command("MISSING-" + type, type, null, null));
        }
        for (RewardType type : List.of(RewardType.POINTS, RewardType.DRAW_CHANCE)) {
            assertTargetInvalid(command("UNEXPECTED-" + type, type, 99L, null));
        }
    }

    @Test
    void productRewardRequiresAnEnabledSku() {
        assertTargetInvalid(command("NO-SKU", RewardType.PRODUCT, Long.MAX_VALUE, null));

        long disabledSkuId = createSku(0);
        assertTargetInvalid(command("DISABLED-SKU", RewardType.PRODUCT, disabledSkuId, null));
    }

    @Test
    void couponAndMembershipRewardsRequireExistingEnabledTargets() {
        assertTargetInvalid(command("NO-COUPON", RewardType.COUPON, Long.MAX_VALUE, null));
        assertTargetInvalid(command("NO-MEMBER", RewardType.MEMBERSHIP, Long.MAX_VALUE, null));
    }

    @Test
    void discreteRewardsRejectUnboundedQuantitiesButPointsRemainLongValued() {
        assertTargetInvalid(new CreateRewardDefinitionCommand(
                "TOO-MANY-DRAWS", "次数过大", RewardType.DRAW_CHANCE, null, 101L, null));
        var points = service.create(new CreateRewardDefinitionCommand(
                "LARGE-POINTS", "大额积分", RewardType.POINTS, null, 100_000L, null));
        assertThat(points.quantity()).isEqualTo(100_000L);
    }

    private long createCoupon(){CouponTemplate t=new CouponTemplate();t.setTemplateCode("C-"+System.nanoTime());t.setTemplateName("券");t.setCouponType(com.dongqh.luckyhub.enums.coupon.CouponType.NO_THRESHOLD);t.setThresholdCent(0L);t.setDiscountCent(10L);t.setValidFrom(LocalDateTime.now().minusDays(1));t.setValidUntil(LocalDateTime.now().plusDays(1));t.setPerUserLimit(10);t.setStackableWithMembership(true);t.setStatus(1);couponMapper.insert(t);return t.getId();}
    private long createMembership(){MembershipProduct p=new MembershipProduct();p.setProductCode("M-"+System.nanoTime());p.setProductName("会员");p.setMembershipLevel("VIP");p.setCardType(com.dongqh.luckyhub.enums.membership.MembershipCardType.MONTH);p.setDurationDays(30);p.setPriceCent(0L);p.setDiscountBasisPoints(9000);p.setDailyDrawBonus(0);p.setPointsMultiplierBasisPoints(10000);p.setStatus(1);membershipMapper.insert(p);return p.getId();}

    @Test
    void translatesDuplicateCodeAndTrimsBusinessStrings() {
        var created = service.create(new CreateRewardDefinitionCommand(
                " POINTS-500 ", " 500积分 ", RewardType.POINTS, null, 500L, null));

        assertThat(created.rewardCode()).isEqualTo("POINTS-500");
        assertThat(created.rewardName()).isEqualTo("500积分");
        assertThatThrownBy(() -> service.create(command("POINTS-500", RewardType.POINTS, null, null)))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(RewardErrorCode.REWARD_CODE_DUPLICATE));
    }

    @Test
    void rejectsMalformedJsonAndMissingDefinitionWithStableErrors() {
        assertThatThrownBy(() -> service.create(command(
                "BAD-JSON", RewardType.POINTS, null, "{not-json}")))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(RewardErrorCode.REWARD_CONFIG_INVALID));

        assertThatThrownBy(() -> service.get(Long.MAX_VALUE))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(RewardErrorCode.REWARD_NOT_FOUND));
    }

    private void assertTargetInvalid(CreateRewardDefinitionCommand command) {
        assertThatThrownBy(() -> service.create(command))
                .isInstanceOfSatisfying(BusinessException.class,
                        exception -> assertThat(exception.getErrorCode())
                                .isEqualTo(RewardErrorCode.REWARD_TARGET_INVALID));
    }

    private CreateRewardDefinitionCommand command(String code, RewardType type, Long targetId, String config) {
        return new CreateRewardDefinitionCommand(code, "测试奖励", type, targetId, 1L, config);
    }

    private long createSku(int status) {
        Product product = new Product();
        product.setProductCode("PROD-" + status + "-" + System.nanoTime());
        product.setProductName("测试商品");
        product.setProductType(ProductType.PHYSICAL);
        product.setStatus(1);
        productMapper.insert(product);

        ProductSku sku = new ProductSku();
        sku.setProductId(product.getId());
        sku.setSkuCode("SKU-" + status + "-" + System.nanoTime());
        sku.setSkuName("默认SKU");
        sku.setCashPriceCent(100L);
        sku.setCashEnabled(true);
        sku.setPointsEnabled(false);
        sku.setStatus(status);
        sku.setVersion(0);
        skuMapper.insert(sku);
        when(hmallCatalog.getItem(sku.getId())).thenReturn(new HmallItemView(
                sku.getId(), sku.getSkuName(), Math.toIntExact(sku.getCashPriceCent()), 10,
                null, "实物", "LuckyHub", null, status));
        return sku.getId();
    }
}

package com.dongqh.luckyhub.reward;

import com.dongqh.luckyhub.domain.po.reward.RewardDefinition;
import com.dongqh.luckyhub.enums.reward.RewardType;
import com.dongqh.luckyhub.mapper.reward.RewardDefinitionMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class RewardDomainContractTests {

    @Autowired RewardDefinitionMapper mapper;

    private Long rewardId;

    @AfterEach
    void cleanUp() {
        if (rewardId != null) {
            mapper.deleteById(rewardId);
        }
    }

    @Test
    void exposesStableRewardTypes() {
        assertThat(RewardType.values()).containsExactly(
                RewardType.PRODUCT,
                RewardType.COUPON,
                RewardType.POINTS,
                RewardType.MEMBERSHIP,
                RewardType.DRAW_CHANCE);
    }

    @Test
    void persistsPointsRewardBusinessFields() {
        RewardDefinition reward = new RewardDefinition();
        reward.setRewardCode("POINTS-" + UUID.randomUUID());
        reward.setRewardName("500积分");
        reward.setRewardType(RewardType.POINTS);
        reward.setTargetId(null);
        reward.setQuantity(500L);
        reward.setConfigSnapshot("{\"source\":\"test\"}");
        reward.setStatus(1);
        mapper.insert(reward);
        rewardId = reward.getId();

        RewardDefinition persisted = mapper.selectById(rewardId);

        assertThat(persisted.getRewardCode()).isEqualTo(reward.getRewardCode());
        assertThat(persisted.getRewardName()).isEqualTo("500积分");
        assertThat(persisted.getRewardType()).isEqualTo(RewardType.POINTS);
        assertThat(persisted.getTargetId()).isNull();
        assertThat(persisted.getQuantity()).isEqualTo(500L);
        assertThat(persisted.getConfigSnapshot()).isEqualTo("{\"source\": \"test\"}");
        assertThat(persisted.getStatus()).isOne();
        assertThat(persisted.getCreatedAt()).isNotNull();
        assertThat(persisted.getUpdatedAt()).isNotNull();
    }
}

package com.dongqh.luckyhub.reward;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.hmall.integration.HmallCatalogClient;
import com.dongqh.luckyhub.domain.hmall.integration.HmallItemView;
import com.dongqh.luckyhub.domain.po.prize.MarketingPrize;
import com.dongqh.luckyhub.enums.prize.PrizeType;
import com.dongqh.luckyhub.enums.reward.RewardType;
import com.dongqh.luckyhub.enums.reward.RewardErrorCode;
import com.dongqh.luckyhub.domain.model.reward.RewardSnapshot;
import com.dongqh.luckyhub.service.reward.RewardSnapshotService;
import com.dongqh.luckyhub.domain.support.reward.RewardPrizeTypeMapping;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.when;

@SpringBootTest
class RewardSnapshotServiceTests {
    @Autowired RewardSnapshotService snapshots;
    @Autowired JdbcTemplate jdbc;
    @MockitoBean HmallCatalogClient hmallCatalog;

    @Test
    void mapsAllRewardTypesToCompatibilityPrizeTypes() {
        assertThat(RewardPrizeTypeMapping.toPrizeType(RewardType.PRODUCT)).isEqualTo(PrizeType.PHYSICAL);
        assertThat(RewardPrizeTypeMapping.toPrizeType(RewardType.COUPON)).isEqualTo(PrizeType.COUPON);
        assertThat(RewardPrizeTypeMapping.toPrizeType(RewardType.POINTS)).isEqualTo(PrizeType.POINTS);
        assertThat(RewardPrizeTypeMapping.toPrizeType(RewardType.MEMBERSHIP)).isEqualTo(PrizeType.MEMBERSHIP);
        assertThat(RewardPrizeTypeMapping.toPrizeType(RewardType.DRAW_CHANCE)).isEqualTo(PrizeType.DRAW_CHANCE);
    }

    @Test
    void createsStableCanonicalPointsSnapshotAndSkipsLegacyPrize() {
        String code = "PHASE5-POINTS-SNAPSHOT";
        jdbc.update("DELETE FROM reward_definition WHERE reward_code=?", code);
        jdbc.update("""
                INSERT INTO reward_definition(reward_code,reward_name,reward_type,target_id,quantity,status)
                VALUES(?,?,'POINTS',NULL,500,1)
                """, code, "500积分");
        Long rewardId = jdbc.queryForObject(
                "SELECT id FROM reward_definition WHERE reward_code=?", Long.class, code);
        try {
            MarketingPrize bound = prize(81001L, rewardId);
            MarketingPrize legacy = prize(81002L, null);
            RewardSnapshot first = snapshots.resolveForPrizes(List.of(bound, legacy)).get(bound.getId());
            RewardSnapshot second = snapshots.resolveForPrizes(List.of(bound)).get(bound.getId());

            assertThat(first.rewardDefinitionId()).isEqualTo(rewardId);
            assertThat(first.rewardType()).isEqualTo(RewardType.POINTS);
            assertThat(first.payloadJson()).isEqualTo("{\"points\":500,\"reason\":\"抽奖奖励\"}");
            assertThat(first.fingerprint()).matches("[0-9a-f]{64}").isEqualTo(second.fingerprint());
            assertThat(snapshots.resolveForPrizes(List.of(bound, legacy))).doesNotContainKey(legacy.getId());
        } finally {
            jdbc.update("DELETE FROM reward_definition WHERE reward_code=?", code);
        }
    }

    @Test
    void resolvesCouponMembershipProductAndDrawChancePayloads() {
        cleanupTargets();
        try {
            jdbc.update("""
                    INSERT INTO coupon_template(template_code,template_name,coupon_type,threshold_cent,
                      discount_cent,valid_from,valid_until,per_user_limit,stackable_with_membership,status)
                    VALUES('P5-COUPON','阶段5券','NO_THRESHOLD',0,100,NOW(),DATE_ADD(NOW(),INTERVAL 30 DAY),10,1,1)
                    """);
            jdbc.update("""
                    INSERT INTO membership_product(product_code,product_name,membership_level,card_type,
                      duration_days,price_cent,discount_basis_points,daily_draw_bonus,points_multiplier_basis_points,status)
                    VALUES('P5-MEMBER','阶段5会员','GOLD','MONTH',30,9900,9000,1,11000,1)
                    """);
            jdbc.update("""
                    INSERT INTO product(product_code,product_name,product_type,status)
                    VALUES('P5-PRODUCT','阶段5实物','PHYSICAL',1)
                    """);
            Long couponId = id("coupon_template", "template_code", "P5-COUPON");
            Long memberId = id("membership_product", "product_code", "P5-MEMBER");
            Long productId = id("product", "product_code", "P5-PRODUCT");
            jdbc.update("""
                    INSERT INTO product_sku(product_id,sku_code,sku_name,cash_enabled,points_enabled,status)
                    VALUES(?,'P5-SKU','红色',0,0,1)
                    """, productId);
            Long skuId = id("product_sku", "sku_code", "P5-SKU");
            when(hmallCatalog.getItem(skuId)).thenReturn(new HmallItemView(
                    skuId, "阶段5实物", 100, 10, null, "实物", "LuckyHub", "红色", 1));
            insertReward("P5-R-COUPON", "COUPON", couponId, 2);
            insertReward("P5-R-MEMBER", "MEMBERSHIP", memberId, 2);
            insertReward("P5-R-PRODUCT", "PRODUCT", skuId, 1);
            insertReward("P5-R-CHANCE", "DRAW_CHANCE", null, 3);

            MarketingPrize coupon = prize(82001L, rewardId("P5-R-COUPON"));
            MarketingPrize member = prize(82002L, rewardId("P5-R-MEMBER"));
            MarketingPrize product = prize(82003L, rewardId("P5-R-PRODUCT"));
            MarketingPrize chance = prize(82004L, rewardId("P5-R-CHANCE"));
            var result = snapshots.resolveForPrizes(List.of(coupon, member, product, chance));

            assertThat(result.get(coupon.getId()).payloadJson())
                    .isEqualTo("{\"templateId\":" + couponId + ",\"templateCode\":\"P5-COUPON\",\"quantity\":2}");
            assertThat(result.get(member.getId()).payloadJson()).contains("\"durationDays\":60", "\"quantity\":2");
            assertThat(result.get(product.getId()).payloadJson()).contains(
                    "\"itemId\":" + skuId,
                    "\"itemName\":\"阶段5实物\"",
                    "\"itemPriceCent\":100");
            assertThat(result.get(chance.getId()).payloadJson()).isEqualTo("{\"chances\":3}");
        } finally {
            cleanupTargets();
        }
    }

    @Test
    void convertsDisabledTargetAndDurationOverflowToStableBusinessError() {
        cleanupTargets();
        try {
            jdbc.update("""
                    INSERT INTO membership_product(product_code,product_name,membership_level,card_type,
                      duration_days,price_cent,discount_basis_points,daily_draw_bonus,points_multiplier_basis_points,status)
                    VALUES('P5-MEMBER','阶段5会员','GOLD','MONTH',30000000,9900,9000,1,11000,1)
                    """);
            Long memberId = id("membership_product", "product_code", "P5-MEMBER");
            insertReward("P5-R-MEMBER", "MEMBERSHIP", memberId, 100);
            MarketingPrize prize = prize(83001L, rewardId("P5-R-MEMBER"));
            assertThatThrownBy(() -> snapshots.resolveForPrizes(List.of(prize)))
                    .isInstanceOfSatisfying(BusinessException.class,
                            error -> assertThat(error.getErrorCode()).isEqualTo(RewardErrorCode.REWARD_TARGET_INVALID));

            jdbc.update("UPDATE membership_product SET duration_days=30,status=0 WHERE id=?", memberId);
            assertThatThrownBy(() -> snapshots.resolveForPrizes(List.of(prize)))
                    .isInstanceOf(BusinessException.class);
        } finally {
            cleanupTargets();
        }
    }

    private void insertReward(String code, String type, Long targetId, long quantity) {
        jdbc.update("INSERT INTO reward_definition(reward_code,reward_name,reward_type,target_id,quantity,status) VALUES(?,?,?, ?,?,1)",
                code, code, type, targetId, quantity);
    }

    private Long rewardId(String code) { return id("reward_definition", "reward_code", code); }

    private Long id(String table, String column, String value) {
        return jdbc.queryForObject("SELECT id FROM " + table + " WHERE " + column + "=?", Long.class, value);
    }

    private void cleanupTargets() {
        jdbc.update("DELETE FROM reward_definition WHERE reward_code LIKE 'P5-R-%'");
        jdbc.update("DELETE FROM product_sku WHERE sku_code='P5-SKU'");
        jdbc.update("DELETE FROM product WHERE product_code='P5-PRODUCT'");
        jdbc.update("DELETE FROM coupon_template WHERE template_code='P5-COUPON'");
        jdbc.update("DELETE FROM membership_product WHERE product_code='P5-MEMBER'");
    }

    private MarketingPrize prize(long id, Long rewardDefinitionId) {
        MarketingPrize prize = new MarketingPrize();
        prize.setId(id);
        prize.setPrizeName("测试奖品");
        prize.setPrizeType(PrizeType.POINTS);
        prize.setRewardDefinitionId(rewardDefinitionId);
        prize.setStatus(1);
        return prize;
    }
}

package com.dongqh.luckyhub.shipping;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.config.shipping.ShippingProperties;
import com.dongqh.luckyhub.domain.crypto.shipping.AesGcmAddressCipher;
import com.dongqh.luckyhub.domain.crypto.shipping.AddressCipher;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.domain.support.shipping.AddressMasker;
import org.junit.jupiter.api.Test;

import java.time.Duration;
import java.util.Base64;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class AddressCipherTests {

    private static final String KEY = "MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=";

    @Test
    void usesVersionedUnpaddedEnvelopeRandomTwelveByteNonceAndRoundTrips() {
        AddressCipher cipher = new AesGcmAddressCipher(properties(KEY, "v1"));

        String first = cipher.encrypt("浙江省杭州市余杭区");
        String second = cipher.encrypt("浙江省杭州市余杭区");

        assertThat(first).isNotEqualTo(second);
        assertThat(first).matches("v1\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+");
        assertThat(first).doesNotContain("=");
        assertThat(Base64.getUrlDecoder().decode(first.split("\\.")[1])).hasSize(12);
        assertThat(Base64.getUrlDecoder().decode(first.split("\\.")[2]).length)
                .isEqualTo("浙江省杭州市余杭区".getBytes(java.nio.charset.StandardCharsets.UTF_8).length + 16);
        assertThat(cipher.decrypt(first)).isEqualTo("浙江省杭州市余杭区");
        assertThat(cipher.decrypt(second)).isEqualTo("浙江省杭州市余杭区");
    }

    @Test
    void rejectsTamperingUnknownVersionMalformedAndEmptyInputWithoutEchoingSecrets() {
        AddressCipher cipher = new AesGcmAddressCipher(properties(KEY, "v1"));
        String envelope = cipher.encrypt("13812345678");
        String tampered = envelope.substring(0, envelope.length() - 1)
                + (envelope.endsWith("A") ? "B" : "A");

        assertSafeFailure(() -> cipher.decrypt(tampered), tampered, KEY, "13812345678");
        assertSafeFailure(() -> cipher.decrypt(envelope.replaceFirst("v1", "v2")), envelope, KEY);
        assertSafeFailure(() -> cipher.decrypt("v1.only-two"), "v1.only-two", KEY);
        assertSafeFailure(() -> cipher.decrypt(""), KEY);
        assertSafeFailure(() -> cipher.encrypt(""), KEY);
    }

    @Test
    void validatesExactAes256KeyVersionAndAllShippingBounds() {
        assertThatThrownBy(() -> properties(Base64.getEncoder().encodeToString(new byte[31]), "v1"))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> properties(KEY, "bad.version"))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new ShippingProperties(KEY, "v1", Duration.ZERO,
                "test-callback-secret-32-bytes-long", Duration.ofMinutes(5), Duration.ofMinutes(1),
                Duration.ZERO, 50)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new ShippingProperties(KEY, "v1", Duration.ofDays(7),
                "short", Duration.ofMinutes(5), Duration.ofMinutes(1), Duration.ZERO, 50))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new ShippingProperties(KEY, "v1", Duration.ofDays(7),
                "test-callback-secret-32-bytes-long", Duration.ofMinutes(5), Duration.ofMinutes(1),
                Duration.ZERO, 1001)).isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void masksReceiverPhoneAndRegionWithoutPlaintextDetail() {
        assertThat(AddressMasker.maskReceiver("张三")).isEqualTo("张*");
        assertThat(AddressMasker.maskReceiver("张")).isEqualTo("*");
        assertThat(AddressMasker.maskPhone("13812345678")).isEqualTo("138****5678");
        assertThat(AddressMasker.maskRegion("浙江省", "杭州市", "余杭区"))
                .isEqualTo("浙江省杭州市余杭区***");
    }

    private ShippingProperties properties(String key, String version) {
        return new ShippingProperties(key, version, Duration.ofDays(7),
                "test-callback-secret-32-bytes-long", Duration.ofMinutes(5), Duration.ofMinutes(1),
                Duration.ofSeconds(60), 50);
    }

    private void assertSafeFailure(Runnable action, String... sensitiveValues) {
        assertThatThrownBy(action::run).isInstanceOfSatisfying(BusinessException.class, exception -> {
            assertThat(exception.getErrorCode()).isEqualTo(ShippingErrorCode.ADDRESS_INVALID);
            for (String sensitive : sensitiveValues) {
                assertThat(exception.getMessage()).doesNotContain(sensitive);
            }
        });
    }
}

