import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class PhysicalBenefitClaimTests {
    UserBenefitMapper benefits = mock(UserBenefitMapper.class);
    LotteryDrawRecordMapper draws = mock(LotteryDrawRecordMapper.class);
    ShippingAddressSnapshotService snapshots = mock(ShippingAddressSnapshotService.class);
    ShippingOrderService orders = mock(ShippingOrderService.class);
    ShippingOrderMapper orderMapper = mock(ShippingOrderMapper.class);
    PhysicalClaimServiceImpl service = new PhysicalClaimServiceImpl(
            benefits, draws, snapshots, orders, orderMapper,
            JsonMapper.builder().findAndAddModules().build());
    String requestId;
    UserBenefit benefit;

    @BeforeEach
    void setUp() {
        requestId = UUID.randomUUID().toString();
        benefit = benefit(LocalDateTime.now().plusDays(1));
        when(benefits.selectByIdForUpdate(31)).thenReturn(benefit);
        when(draws.selectById(21L)).thenReturn(draw(benefit));
    }

    @Test
    void eligibleClaimCreatesSnapshotAndUnifiedShippingThenAttachesIt() {
        ShippingAddressSnapshot snapshot = new ShippingAddressSnapshot();
        snapshot.setId(41L);
        when(snapshots.create(11, 51, ShippingSourceType.LOTTERY_BENEFIT, "31"))
                .thenReturn(snapshot);
        ShippingOrderView expected = view();
        when(orders.create(any())).thenReturn(expected);
        when(benefits.markClaimed(eq(31L), eq(61L), any())).thenReturn(1);

        assertThat(service.claim(11, 31, new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isEqualTo(expected);
        verify(orders).create(argThat(command -> command.claimRequestId().equals(requestId)
                && command.hmallItemId().equals(91L)
                && command.skuCode().equals("HMALL-ITEM-91") && command.quantity() == 2));
        verify(benefits).markClaimed(eq(31L), eq(61L), any());
    }

    @Test
    void crossUserAndNonProductAreBoundedWithoutCreatingSideEffects() {
        assertThatThrownBy(() -> service.claim(12, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isInstanceOfSatisfying(BusinessException.class, error ->
                        assertThat(error.getErrorCode()).isEqualTo(ShippingErrorCode.CLAIM_NOT_ALLOWED));
        benefit.setPrizeType(PrizeType.COUPON);
        assertThatThrownBy(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isInstanceOf(BusinessException.class);
        verifyNoInteractions(snapshots, orders);
    }

    @Test
    void deadlineEqualityIsExpired() {
        benefit.setClaimDeadline(LocalDateTime.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS));
        assertThatThrownBy(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isInstanceOfSatisfying(BusinessException.class, error ->
                        assertThat(error.getErrorCode()).isEqualTo(ShippingErrorCode.CLAIM_EXPIRED));
        verifyNoInteractions(snapshots, orders);
    }

    @Test
    void malformedUuidIsRejectedBeforeLockingTheBenefit() {
        assertThatThrownBy(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand("not-a-uuid", 51L)))
                .isInstanceOfSatisfying(BusinessException.class, error ->
                        assertThat(error.getErrorCode()).isEqualTo(ShippingErrorCode.SHIPPING_REQUEST_INVALID));
        verifyNoInteractions(benefits);
    }

    @Test
    void exactRetryReturnsExistingOrderEvenAfterClaimDeadline() {
        benefit.setStatus(BenefitStatus.FULFILLING);
        benefit.setShippingOrderId(61L);
        benefit.setClaimDeadline(LocalDateTime.now().minusDays(1));
        ShippingOrder existing = existingOrder(requestId, 51L);
        ShippingOrderView expected = view();
        when(orderMapper.lockBySource(ShippingSourceType.LOTTERY_BENEFIT, "31")).thenReturn(existing);
        when(orders.getForUser(11, "SHIPPING-61")).thenReturn(expected);

        assertThat(service.claim(11, 31, new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isEqualTo(expected);
        verify(snapshots).require(41L);
        verify(snapshots, never()).create(anyLong(), anyLong(), any(), anyString());
        verify(orders, never()).create(any());
    }

    @Test
    void existingOrderMustBeLinkedFromBenefitAndInClaimedLifecycle() {
        ShippingOrder existing = existingOrder(requestId, 51L);
        when(orderMapper.lockBySource(ShippingSourceType.LOTTERY_BENEFIT, "31")).thenReturn(existing);
        benefit.setStatus(BenefitStatus.FULFILLING);
        benefit.setShippingOrderId(999L);

        assertIdempotencyConflict(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)));

        benefit.setShippingOrderId(61L);
        benefit.setStatus(BenefitStatus.CLAIM_EXPIRED);
        assertThatThrownBy(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)))
                .isInstanceOfSatisfying(BusinessException.class, error ->
                        assertThat(error.getErrorCode()).isEqualTo(ShippingErrorCode.CLAIM_NOT_ALLOWED));
    }

    @Test
    void existingOrderRejectsChangedAddressRequestOrFrozenIdentity() {
        benefit.setStatus(BenefitStatus.SHIPPED);
        benefit.setShippingOrderId(61L);
        ShippingOrder existing = existingOrder(requestId, 51L);
        when(orderMapper.lockBySource(ShippingSourceType.LOTTERY_BENEFIT, "31"))
                .thenReturn(existing);

        assertIdempotencyConflict(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 52L)));
        assertIdempotencyConflict(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(UUID.randomUUID().toString(), 51L)));
        benefit.setRewardPayload("{\"itemId\":92,\"itemName\":\"礼盒\",\"itemImage\":null,\"itemPriceCent\":9900,\"quantity\":2}");
        assertIdempotencyConflict(() -> service.claim(11, 31,
                new ClaimPhysicalBenefitCommand(requestId, 51L)));
    }

    private void assertIdempotencyConflict(org.assertj.core.api.ThrowableAssert.ThrowingCallable call) {
        assertThatThrownBy(call).isInstanceOfSatisfying(BusinessException.class, error ->
                assertThat(error.getErrorCode()).isEqualTo(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT));
    }

    private ShippingOrder existingOrder(String claimRequestId, long addressId) {
        ShippingAddressSnapshot snapshot = new ShippingAddressSnapshot();
        snapshot.setId(41L); snapshot.setAddressId(addressId);
        when(snapshots.require(41L)).thenReturn(snapshot);
        ShippingOrder order = new ShippingOrder();
        order.setId(61L); order.setShippingNo("SHIPPING-61"); order.setTargetUserId(11L);
        order.setAddressSnapshotId(41L); order.setClaimRequestId(claimRequestId);
        order.setSkuCode("HMALL-ITEM-91"); order.setProductName("礼盒"); order.setQuantity(2);
        return order;
    }

    private UserBenefit benefit(LocalDateTime deadline) {
        UserBenefit row = new UserBenefit();
        row.setId(31L); row.setDrawRecordId(21L); row.setUserId(11L); row.setPrizeId(71L);
        row.setPrizeType(PrizeType.PHYSICAL); row.setRewardDefinitionId(81L);
        row.setRewardType(RewardType.PRODUCT); row.setRewardTargetId(91L); row.setRewardQuantity(2L);
        row.setRewardPayload("{\"itemId\":91,\"itemName\":\"礼盒\",\"itemImage\":null,\"itemPriceCent\":9900,\"quantity\":2}");
        row.setRewardFingerprint("a".repeat(64)); row.setQuantity(2);
        row.setStatus(BenefitStatus.CLAIM_PENDING); row.setClaimDeadline(deadline);
        return row;
    }

    private LotteryDrawRecord draw(UserBenefit row) {
        LotteryDrawRecord draw = new LotteryDrawRecord();
        draw.setId(21L); draw.setUserId(row.getUserId()); draw.setActivityId(101L);
        draw.setPrizeId(row.getPrizeId()); draw.setPrizeType(row.getPrizeType());
        draw.setPrizeImageUrl("https://example.test/prize.png");
        draw.setRewardDefinitionId(row.getRewardDefinitionId()); draw.setRewardType(row.getRewardType());
        draw.setRewardTargetId(row.getRewardTargetId()); draw.setRewardQuantity(row.getRewardQuantity());
        draw.setRewardPayload(row.getRewardPayload()); draw.setRewardFingerprint(row.getRewardFingerprint());
        return draw;
    }

    private ShippingOrderView view() {
        return new ShippingOrderView(61L, "SHIPPING-61", ShippingSourceType.LOTTERY_BENEFIT,
                "31", 11L, 41L, "HMALL-ITEM-91", "礼盒", null, 2, "LOGISTICS-61",
                null, null, null, ShippingStatus.FULFILLING, null, null,
                null, null, null, null, LocalDateTime.now(), LocalDateTime.now());
    }
}

package com.dongqh.luckyhub.shipping;

import com.dongqh.luckyhub.domain.dto.shipping.ClaimPhysicalBenefitCommand;
import com.dongqh.luckyhub.service.shipping.PhysicalClaimService;
import com.dongqh.luckyhub.service.shipping.PhysicalClaimExpiryService;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingOrderView;
import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.reset;

@SpringBootTest
class PhysicalClaimConcurrencyTests extends Task5ShippingTestFixture {
    @Autowired PhysicalClaimService claims;
    @Autowired PhysicalClaimExpiryService expiry;
    @MockitoSpyBean UserBenefitMapper benefitMapperSpy;
    private Long benefitId;
    private Long drawRecordId;
    private Long drawOrderId;
    private Long activityPrizeId;
    private Long activityId;
    private Long prizeId;
    private Long rewardId;

    @AfterEach
    void cleanLotteryFixture() {
        if (benefitId != null) jdbc.update("DELETE FROM inventory_ledger WHERE business_no=?", "CLAIM-EXPIRE-" + benefitId);
        if (benefitId != null) jdbc.update("DELETE FROM user_benefit WHERE id=?", benefitId);
        if (drawRecordId != null) jdbc.update("DELETE FROM lottery_draw_record WHERE id=?", drawRecordId);
        if (drawOrderId != null) jdbc.update("DELETE FROM lottery_draw_order WHERE id=?", drawOrderId);
        if (activityPrizeId != null) jdbc.update("DELETE FROM marketing_activity_prize WHERE id=?", activityPrizeId);
        if (activityId != null) jdbc.update("DELETE FROM marketing_activity WHERE id=?", activityId);
        if (prizeId != null) jdbc.update("DELETE FROM marketing_prize WHERE id=?", prizeId);
        if (rewardId != null) jdbc.update("DELETE FROM reward_definition WHERE id=?", rewardId);
    }

    @Test
    void twentySameIdentityClaimsCreateExactlyOneSnapshotOrderAndLogisticsTask() throws Exception {
        long userId = createUser();
        long addressId = createAddress(userId);
        long skuId = createPhysicalSku(true, false);
        createPendingBenefit(userId, skuId, LocalDateTime.now().plusDays(1));
        String requestId = UUID.randomUUID().toString();
        var pool = Executors.newFixedThreadPool(20);
        try {
            List<Callable<ShippingOrderView>> calls = new ArrayList<>();
            for (int i = 0; i < 20; i++) {
                calls.add(() -> claims.claim(userId, benefitId,
                        new ClaimPhysicalBenefitCommand(requestId, addressId)));
            }
            List<ShippingOrderView> results = pool.invokeAll(calls).stream()
                    .map(future -> {
                        try { return future.get(); }
                        catch (Exception exception) { throw new AssertionError(exception); }
                    }).toList();
            ShippingOrderView winner = results.get(0);
            trackFulfillment(winner.fulfillmentNo());
            assertThat(results).allSatisfy(result -> assertThat(result.id()).isEqualTo(winner.id()));
            assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM shipping_address_snapshot WHERE source_type='LOTTERY_BENEFIT' AND source_id=?", Integer.class, benefitId.toString())).isOne();
            assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM shipping_order WHERE source_type='LOTTERY_BENEFIT' AND source_id=?", Integer.class, benefitId.toString())).isOne();
            assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM fulfillment_task WHERE fulfillment_no=?", Integer.class, winner.fulfillmentNo())).isOne();
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void claimAndExpiryAtTheSameInstantHaveExactlyOneLockedWinner() throws Exception {
        long userId = createUser();
        long addressId = createAddress(userId);
        long skuId = createPhysicalSku(true, false);
        LocalDateTime deadline = LocalDateTime.now().plusSeconds(1);
        createPendingBenefit(userId, skuId, deadline);
        int stockBefore = jdbc.queryForObject("SELECT remaining_stock FROM marketing_activity_prize WHERE id=?",
                Integer.class, activityPrizeId);
        String requestId = UUID.randomUUID().toString();
        CountDownLatch start = new CountDownLatch(1);
        var pool = Executors.newFixedThreadPool(2);
        try {
            var claimFuture = pool.submit(() -> {
                start.await();
                try { return claims.claim(userId, benefitId, new ClaimPhysicalBenefitCommand(requestId, addressId)); }
                catch (RuntimeException rejected) { return null; }
            });
            var expiryFuture = pool.submit(() -> {
                start.await();
                return expiry.expireDue(10, deadline);
            });
            start.countDown();
            ShippingOrderView claimed = claimFuture.get();
            int expired = expiryFuture.get();
            String status = jdbc.queryForObject("SELECT status FROM user_benefit WHERE id=?", String.class, benefitId);
            int stockAfter = jdbc.queryForObject("SELECT remaining_stock FROM marketing_activity_prize WHERE id=?",
                    Integer.class, activityPrizeId);
            if (claimed != null) {
                trackFulfillment(claimed.fulfillmentNo());
                assertThat(expired).isZero();
                assertThat(status).isEqualTo("FULFILLING");
                assertThat(stockAfter).isEqualTo(stockBefore);
            } else {
                assertThat(expired).isOne();
                assertThat(status).isEqualTo("CLAIM_EXPIRED");
                assertThat(stockAfter).isEqualTo(stockBefore + 1);
            }
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void claimFailureRollsBackSnapshotOrderTaskAndBenefitLink() {
        long userId = createUser();
        long addressId = createAddress(userId);
        long skuId = createPhysicalSku(true, false);
        createPendingBenefit(userId, skuId, LocalDateTime.now().plusDays(1));
        doReturn(0).when(benefitMapperSpy).markClaimed(eq(benefitId), any(Long.class), any(LocalDateTime.class));
        try {
            assertThatThrownBy(() -> claims.claim(userId, benefitId,
                    new ClaimPhysicalBenefitCommand(UUID.randomUUID().toString(), addressId)))
                    .isInstanceOf(RuntimeException.class);
        } finally {
            reset(benefitMapperSpy);
        }
        assertThat(jdbc.queryForObject("SELECT status FROM user_benefit WHERE id=?", String.class, benefitId))
                .isEqualTo("CLAIM_PENDING");
        assertThat(jdbc.queryForObject("SELECT shipping_order_id FROM user_benefit WHERE id=?",
                Long.class, benefitId)).isNull();
        assertThat(jdbc.queryForObject("SELECT claimed_at FROM user_benefit WHERE id=?",
                LocalDateTime.class, benefitId)).isNull();
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM shipping_address_snapshot WHERE source_type='LOTTERY_BENEFIT' AND source_id=?",
                Integer.class, benefitId.toString())).isZero();
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM shipping_order WHERE source_type='LOTTERY_BENEFIT' AND source_id=?",
                Integer.class, benefitId.toString())).isZero();
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM fulfillment_task WHERE source_type='LOTTERY_BENEFIT' AND source_id=?",
                Integer.class, benefitId.toString())).isZero();
    }

    @Test
    void poisonExpiryRollsBackLedgerStockAndBenefitState() {
        long userId = createUser();
        long skuId = createPhysicalSku(true, false);
        LocalDateTime now = LocalDateTime.now();
        createPendingBenefit(userId, skuId, now.minusSeconds(1));
        int stockBefore = jdbc.queryForObject("SELECT remaining_stock FROM marketing_activity_prize WHERE id=?",
                Integer.class, activityPrizeId);
        doReturn(0).when(benefitMapperSpy).markClaimExpired(eq(benefitId), eq(now));
        try {
            assertThat(expiry.expireDue(1, now)).isZero();
        } finally {
            reset(benefitMapperSpy);
        }
        assertThat(jdbc.queryForObject("SELECT status FROM user_benefit WHERE id=?", String.class, benefitId))
                .isEqualTo("CLAIM_PENDING");
        assertThat(jdbc.queryForObject("SELECT remaining_stock FROM marketing_activity_prize WHERE id=?",
                Integer.class, activityPrizeId)).isEqualTo(stockBefore);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM inventory_ledger WHERE business_no=?",
                Integer.class, "CLAIM-EXPIRE-" + benefitId)).isZero();
    }

    private void createPendingBenefit(long userId, long skuId, LocalDateTime deadline) {
        String suffix = UUID.randomUUID().toString();
        String payload = "{\"itemId\":" + skuId
                + ",\"itemName\":\"并发礼盒\",\"itemImage\":null,\"itemPriceCent\":100,\"quantity\":1}";
        String fingerprint = "a".repeat(64);
        rewardId = insert("reward_definition", map("reward_code", "TASK4-R-" + suffix,
                "reward_name", "领取奖励", "reward_type", "PRODUCT", "target_id", skuId,
                "quantity", 1, "config_snapshot", payload, "status", 1));
        prizeId = insert("marketing_prize", map("prize_name", "并发实物", "prize_type", "PHYSICAL",
                "reward_definition_id", rewardId, "prize_level", "FIRST", "image_url", "https://example.test/gift.png",
                "stackable", 0, "status", 1));
        activityId = insert("marketing_activity", map("activity_name", "TASK4-A-" + suffix,
                "status", "RUNNING", "start_time", LocalDateTime.now().minusDays(1),
