package com.dongqh.membershipservice.config.membership;

import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.Declarables;
import org.springframework.amqp.core.DirectExchange;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
@ConditionalOnProperty(prefix = "membership.messaging", name = "enabled", havingValue = "true")
public class MembershipPayMessagingConfiguration {
    public static final String EXCHANGE = "pay.direct";
    public static final String DLX = "pay.dlx";
    public static final String ROUTING_KEY = "pay.membership.success";
    public static final String QUEUE = "membership.pay.success.queue";
    public static final String DLQ = "membership.pay.success.dlq";

    @Bean
    public Declarables membershipPayTopology() {
        DirectExchange exchange = new DirectExchange(EXCHANGE, true, false);
        DirectExchange deadLetterExchange = new DirectExchange(DLX, true, false);
        Queue queue = QueueBuilder.durable(QUEUE).deadLetterExchange(DLX).build();
        Queue deadLetterQueue = QueueBuilder.durable(DLQ).build();
        return new Declarables(exchange, deadLetterExchange, queue, deadLetterQueue,
                BindingBuilder.bind(queue).to(exchange).with(ROUTING_KEY),
                BindingBuilder.bind(deadLetterQueue).to(deadLetterExchange).with(ROUTING_KEY));
    }
}

package com.dongqh.membershipservice.controller.membership;

import com.dongqh.hmapi.dto.MembershipBenefitDTO;
import com.dongqh.hmapi.dto.MembershipRewardProductDTO;
import com.dongqh.membershipservice.service.membership.MembershipQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/internal/memberships")
@RequiredArgsConstructor
public class InternalMembershipBenefitController {
    private final MembershipQueryService memberships;

    @GetMapping("/{userId}/benefit")
    public MembershipBenefitDTO activeBenefit(@PathVariable("userId") Long userId) {
        return memberships.activeBenefit(userId)
                .map(benefit -> new MembershipBenefitDTO(true, benefit.discountBasisPoints(),
                        benefit.membershipLevel(), benefit.expiresAt()))
                .orElseGet(() -> new MembershipBenefitDTO(false, null, null, null));
    }

    @GetMapping("/products/{productId}/reward")
    public MembershipRewardProductDTO getRewardProduct(@PathVariable("productId") long productId) {
        return memberships.getEnabledRewardProduct(productId);
    }
}

