.circle{
    position: absolute;
    top: 0;
    left: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background-color: #fff;
    box-shadow: 0 0 3px 1px rgba(0, 0, 0, 0.5);
}
.button-label .text {
    line-height: 20px;
    font-size: 12px;

    /*
    用来阻止页面文字被选中，出现蓝色
    可以将下面两行代码注释掉来查看区别
    */
    -webkit-user-select: none;
    user-select: none;
}
.on {
    color: #fff;
    display: none;
    text-indent: 0;
}
.off {
    color: #fff;
    display: inline-block;
    text-indent: 0;
}
.button-label .circle{
    left: 0;
    transition: all 0.3s;/*transition过度，时间为0.3秒*/
}

/*
