/*!components/css-modules/base.css*/
body, html {
	margin: 0;
	padding: 0;
	font: 12px "宋体";
	color: #666
}

.py-container {
	width: 1200px;
	margin: 0 auto
}

h1, h2, h3, h4, h5 {
	font-family: "微软雅黑";
	font-weight: 400
}

h3 {
	font-size: 18px
}

h4 {
	font-size: 16px
}

h5 {
	font-size: 14px
}

h3, p {
	margin: 5px 0
}

.top, .sort, .show, .like, .fun, .floor, .brand, .footer {
	height: auto
}

.clearfix {
	clear: both
}

.bold {
	font-weight: 700
}

.tip {
	font-size: 12px;
	font-weight: 400
}

.fl {
	float: left
}

.fr {
	float: right
}

a:hover {
	color: #e82633
}

em {
	font-style: normal !important
}

i {
	font-style: normal !important
}
/*!components/css-modules/nav.css*/
div.yui3-g>div.yui3-u {
	height: 100%
}

ul.yui3-g>li {
	height: 100%
}

ul.brand-list li {
	height: 57px;
	line-height: 58px
}

.yui3-u {
	_zoom: 1;
	*display: inline
}

.Left {
	width: 210px
}

.Center {
	width: 740px;
	position: relative;
}

.Right {
	width: 250px;
	position: relative
}

.sui-form {
	margin: 0
}

.top {
	background-color: #EAEAEA;
	line-height: 30px
}

.shortcut {
	height: 30px
}

.Logo {
	height: 105px
}

.NavList {
	height: 45px
}

.SortList {
	height: 460px
}

.space {
	width: 1px;
	height: 13px;
	background: #666;
	margin: 8px 10px
}

.shortcut ul li {
	line-height: 30px
}

.f-item, .Brand-item, .grid-service-item {
	list-style-type: none;
	float: left;
	position: relative
}

.f-item .service {
	display: none;
	position: absolute;
	right: -12px;
	width: 120px;
	padding: 0;
	z-index: 2;
	background-color: #EAEAEA;
	color: #626060;
	padding-left: 25px
}

.f-item .service li {
	list-style-type: none;
	float: left;
	margin-right: 8px
}

.f-item .service li a {
	text-decoration: none
}

.header {
	border-bottom: 2px solid #b1191a
}

.logo-bd {
	display: block;
	background: url(../img/Logo.png) no-repeat;
	width: 175px;
	height: 55px;
	margin: 25px auto
}

.searchArea .hotwords {
	width: 570px;
	margin: 0 auto;
	overflow: hidden
}

.searchArea .hotwords ul {
	overflow: hidden
}

.searchArea .search {
	width: 570px;
	margin: 30px auto -10px
}

.search .input-append .input-error {
	border-radius: 0;
	padding: 5px;
	border: 2px solid #c81523 !important
}

.search .input-append .btn-danger {
	border-radius: 0;
	border-color: #c81523;
	background: #c81523;
	font-family: "微软雅黑";
	line-height: 22px;
	height: 32px
}

.hotwords ul li {
	padding: 5px 25px 0 0
}

.hotwords ul li:first-child {
	color: red
}

.shopArea .shopcar {
	width: 180px;
	margin: 30px auto -1px;
	position: relative
}

.shopArea .shopcar a {
	padding: 4px 42px
}

.shopArea .car {
	background-image: url(../img/icons.png);
	background-position: 160px -81px;
	position: absolute;
	width: 30px;
	height: 30px;
	padding: 0 7px
}

.shopcar .btn-default {
	border: 1px solid #dfdfdf;
	background: #f7f7f7;
	border-radius: 0;
	font-size: 12px
}

.shopcarlist {
	width: 194px;
	margin: -1px 0 0 -70px;
	border: 1px solid #dadada;
	padding: 10px;
	display: none;
	background: #fff
}

.shopnum {
	position: absolute;
	background: #c81623;
	color: #fff;
	padding: 4px;
	border-radius: 6px;
	height: 6px;
	top: -5px;
	right: 62px;
	font-size: 8px;
	line-height: 6px
}

.NavList .all-sort {
	background: #b1191a;
	color: #fff;
	text-align: center
}

.all-sort h4 {
	margin: 12px 0
}

.SortList .all-sort-list {
	background: #c81623
}

.navArea ul.nav li {
	font: 16px "微软雅黑";
	padding: 0 25px;
	line-height: 45px
}

.brand ul.Brand-list>li {
	width: 120px
}

.Mod-service ul.Mod-Service-list>li {
	width: 230px
}

.footer {
	background-color: #EAEAEA
}

.footer .footlink {
	margin: 0 15px
}

.Mod-list, .Mod-service, .Mod-copyright {
	padding: 20px
}

.Mod-service {
	overflow: hidden;
	padding: 15px 10px
}

.Mod-service ul.Mod-Service-list li .intro {
	width: 170px;
	margin: 0 auto
}

.intro1, .intro2, .intro3, .intro4, .intro5 {
	overflow: hidden
}

.serivce-item, .service-text {
	margin-top: 15px;
	padding-left: 10px
}

.service-text h4 {
	margin: 0
}

.grid-service-item .serivce-item {
	background-image: url(../img/icons.png);
	width: 49px;
	height: 50px
}

.intro1 .serivce-item {
	background-position: 307px -3px
}

.intro2 .serivce-item {
	background-position: 307px -53px
}

.intro3 .serivce-item {
	background-position: 307px -106px
}

.intro4 .serivce-item {
	background-position: 307px -156px
}

.intro5 .serivce-item {
	background-position: 307px -208px
}

.Mod-list {
	border-bottom: 1px solid #e4e1e1;
	border-top: 1px solid #e4e1e1
}

.Mod-list .yui3-g {
	padding-left: 30px
}

.Mod-list h4 {
	font-size: 16px;
	font-weight: 400
}

.Mod-copyright ul.helpLink li {
	list-style-type: none;
	display: inline-block;
	_zoom: 1;
	*display: inline
}

.Mod-copyright ul.helpLink li .space {
	border-left: 1px solid #666
}

.Mod-copyright {
	text-align: center
}

#service span {
	color: #68BAED;
	cursor: pointer
}

#service ul li a {
	color: #555
}

#service ul li a:hover {
	color: #68BAED
}
