import com.dongqh.hmapi.dto.CouponCheckoutItemDTO;
import com.dongqh.hmapi.dto.CouponOrderBindingRequest;
import com.dongqh.hmapi.dto.CouponReservationDTO;
import com.dongqh.hmapi.dto.OrderDetailDTO;
import com.dongqh.hmapi.dto.ReserveCouponRequest;
import com.dongqh.tradeservice.utils.AuthorizationContext;
import com.hmall.common.domain.R;
import com.hmall.common.exception.BadRequestException;
import feign.FeignException;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

import java.util.List;

@Component
@ConditionalOnProperty(prefix = "trade.coupon-checkout-service", name = "enabled", havingValue = "true")
public class CouponServiceCheckoutClient implements CouponCheckoutClient {
    private final CouponClient coupons;

    public CouponServiceCheckoutClient(CouponClient coupons) {
        this.coupons = coupons;
    }

    @Override
    public CouponReservationView reserve(Long couponId, Long orderId, List<OrderDetailDTO> details) {
        ReserveCouponRequest request = new ReserveCouponRequest(couponId, orderId.toString(), details.stream()
                .map(detail -> new CouponCheckoutItemDTO(detail.getItemId(), detail.getNum()))
                .toList());
        try {
            R<CouponReservationDTO> response = coupons.reserveForCheckout(AuthorizationContext.require(), request);
            CouponReservationDTO data = response == null || !response.success() ? null : response.getData();
            if (data == null || data.discountCent() == null
                    || data.discountCent() < Integer.MIN_VALUE || data.discountCent() > Integer.MAX_VALUE) {
                throw new BadRequestException("优惠券预占失败");
            }
            return new CouponReservationView(data.userCouponId(), data.templateId(), data.couponName(),
                    data.discountCent().intValue());
        } catch (FeignException exception) {
            throw new BadRequestException("优惠券不可用或不适用于当前订单");
        }
    }

    @Override
    public void use(Long couponId, Long orderId) {
        try {
            R<Void> response = coupons.useForCheckout(AuthorizationContext.require(), couponId,
                    new CouponOrderBindingRequest(orderId.toString()));
            if (response == null || !response.success()) throw new BadRequestException("优惠券核销失败");
        } catch (FeignException exception) {
            throw new BadRequestException("优惠券核销失败");
        }
    }

    @Override
    public void release(Long couponId, Long orderId) {
        try {
            R<Void> response = coupons.releaseForCheckout(AuthorizationContext.require(), couponId,
                    orderId.toString());
            if (response == null || !response.success()) throw new BadRequestException("优惠券释放失败");
        } catch (FeignException exception) {
            throw new BadRequestException("优惠券释放失败");
        }
    }
}

package com.dongqh.tradeservice.marketing;

import com.dongqh.hmapi.dto.OrderDetailDTO;
import com.dongqh.tradeservice.utils.AuthorizationContext;
import com.hmall.common.exception.BadRequestException;
import lombok.Data;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.restclient.RestTemplateBuilder;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.util.UriComponentsBuilder;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Component
@ConditionalOnProperty(prefix = "trade.coupon-checkout-service", name = "enabled",
        havingValue = "false", matchIfMissing = true)
public class HttpCouponCheckoutClient implements CouponCheckoutClient {
    private final RestTemplate restTemplate;
    private final String checkoutUrl;

    @Autowired
    public HttpCouponCheckoutClient(
            RestTemplateBuilder builder,
            @Value("${hm.marketing.base-url}") String marketingBaseUrl) {
        this(builder.build(), stripTrailingSlash(marketingBaseUrl) + "/api/coupons/checkout");
    }

    HttpCouponCheckoutClient(RestTemplate restTemplate, String checkoutUrl) {
        this.restTemplate = restTemplate;
        this.checkoutUrl = stripTrailingSlash(checkoutUrl);
    }

    @Override
    public CouponReservationView reserve(Long couponId, Long orderId, List<OrderDetailDTO> details) {
        Map<String, Object> request = Map.of(
                "couponId", couponId,
                "orderNo", orderId.toString(),
                "items", details.stream()
                        .map(detail -> Map.<String, Object>of(
                                "itemId", detail.getItemId(),
                                "quantity", detail.getNum()))
                        .collect(Collectors.toList()));
        try {
            ResponseEntity<ApiResponse<CouponReservationView>> response = restTemplate.exchange(
                    checkoutUrl + "/reservations",
                    HttpMethod.POST,
                    new HttpEntity<>(request, authorizedHeaders()),
                    new org.springframework.core.ParameterizedTypeReference<ApiResponse<CouponReservationView>>() {
                    });
            ApiResponse<CouponReservationView> body = response.getBody();
            if (body == null || body.getData() == null) {
                throw new BadRequestException("优惠券预占失败");
            }
            return body.getData();
        } catch (RestClientException exception) {
            throw new BadRequestException("优惠券不可用或不适用于当前订单");
        }
    }

    @Override
    public void use(Long couponId, Long orderId) {
        transition(couponId, orderId, HttpMethod.PUT, "/used");
    }

    @Override
    public void release(Long couponId, Long orderId) {
        String url = UriComponentsBuilder.fromUriString(checkoutUrl + "/reservations/{couponId}")
                .queryParam("orderNo", orderId.toString())
                .buildAndExpand(couponId)
                .toUriString();
        try {
            restTemplate.exchange(url, HttpMethod.DELETE,
                    new HttpEntity<>(authorizedHeaders()), Void.class);
        } catch (RestClientException exception) {
            throw new BadRequestException("优惠券释放失败");
        }
    }

    private void transition(Long couponId, Long orderId, HttpMethod method, String suffix) {
        Map<String, Object> request = Map.of("orderNo", orderId.toString());
        try {
            restTemplate.exchange(checkoutUrl + "/reservations/" + couponId + suffix,
                    method, new HttpEntity<>(request, authorizedHeaders()), Void.class);
        } catch (RestClientException exception) {
            throw new BadRequestException("优惠券核销失败");
        }
    }

    private HttpHeaders authorizedHeaders() {
        HttpHeaders headers = new HttpHeaders();
        headers.set(HttpHeaders.AUTHORIZATION, AuthorizationContext.require());
        return headers;
    }

    private static String stripTrailingSlash(String value) {
        return value != null && value.endsWith("/") ? value.substring(0, value.length() - 1) : value;
    }

    @Data
    private static class ApiResponse<T> {
        private int code;
        private String message;
        private T data;
    }
}

package com.dongqh.tradeservice.marketing;


import com.dongqh.tradeservice.utils.AuthorizationContext;
import lombok.Data;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.restclient.RestTemplateBuilder;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

import java.time.LocalDateTime;

@Component
@ConditionalOnProperty(prefix = "trade.membership-benefit-service", name = "enabled",
        havingValue = "false", matchIfMissing = true)
public class HttpMembershipBenefitClient implements MembershipBenefitClient {
    private static final int FULL_PRICE_BASIS_POINTS = 10_000;

    private final RestTemplate restTemplate;
    private final String membershipUrl;

    @Autowired
    public HttpMembershipBenefitClient(
            RestTemplateBuilder builder,
            @Value("${hm.marketing.base-url}") String marketingBaseUrl) {
        this(builder.build(), stripTrailingSlash(marketingBaseUrl) + "/api/memberships/me");
    }

    HttpMembershipBenefitClient(RestTemplate restTemplate, String membershipUrl) {
        this.restTemplate = restTemplate;
        this.membershipUrl = membershipUrl;
    }

    @Override
    public MembershipBenefitView getActiveBenefit() {
        HttpHeaders headers = new HttpHeaders();
        headers.set(HttpHeaders.AUTHORIZATION, AuthorizationContext.require());
        MembershipResponse response = restTemplate.exchange(
                membershipUrl,
                HttpMethod.GET,
                new HttpEntity<>(headers),
                MembershipResponse.class).getBody();
        if (response == null || response.getCode() != 0) {
            throw new IllegalStateException("会员权益查询失败");
        }
        MembershipData data = response.getData();
        if (data == null || data.getExpiresAt() == null || !data.getExpiresAt().isAfter(LocalDateTime.now())) {
            return new MembershipBenefitView(null, FULL_PRICE_BASIS_POINTS, null);
        }
        Integer basisPoints = data.getDiscountBasisPoints();
        if (basisPoints == null || basisPoints <= 0 || basisPoints > FULL_PRICE_BASIS_POINTS) {
            throw new IllegalStateException("会员折扣参数无效");
        }
        return new MembershipBenefitView(data.getMembershipLevel(), basisPoints, data.getExpiresAt());
    }

    private static String stripTrailingSlash(String value) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException("营销服务地址不能为空");
        }
        String normalized = value.trim();
        while (normalized.endsWith("/")) {
            normalized = normalized.substring(0, normalized.length() - 1);
        }
        return normalized;
    }

    @Data
    public static class MembershipResponse {
        private int code;
        private String message;
        private MembershipData data;
    }

    @Data
    public static class MembershipData {
        private String membershipLevel;
        private Integer discountBasisPoints;
        private LocalDateTime expiresAt;
    }
}

