package com.dongqh.tradeservice.marketing;

import com.dongqh.hmapi.client.MembershipClient;
import com.dongqh.hmapi.dto.MembershipBenefitDTO;
import com.hmall.common.utils.UserContext;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
@ConditionalOnProperty(prefix = "trade.membership-benefit-service", name = "enabled", havingValue = "true")
public class MembershipServiceBenefitClient implements MembershipBenefitClient {
    private static final int FULL_PRICE_BASIS_POINTS = 10_000;

    private final MembershipClient memberships;

    public MembershipServiceBenefitClient(MembershipClient memberships) {
        this.memberships = memberships;
    }

    @Override
    public MembershipBenefitView getActiveBenefit() {
        Long userId = UserContext.getUser();
        if (userId == null || userId <= 0) {
            throw new IllegalStateException("当前请求缺少可信用户身份");
        }
        MembershipBenefitDTO benefit = memberships.activeBenefit(userId);
        if (benefit == null || benefit.active() == null) {
            throw new IllegalStateException("会员服务返回了无效的权益响应");
        }
        if (!benefit.active() || benefit.expiresAt() == null
                || !benefit.expiresAt().isAfter(LocalDateTime.now())) {
            return new MembershipBenefitView(null, FULL_PRICE_BASIS_POINTS, null);
        }
        Integer basisPoints = benefit.discountBasisPoints();
        if (basisPoints == null || basisPoints <= 0 || basisPoints > FULL_PRICE_BASIS_POINTS) {
            throw new IllegalStateException("会员服务返回了无效的折扣参数");
        }
        return new MembershipBenefitView(benefit.membershipLevel(), basisPoints, benefit.expiresAt());
    }
}

package com.dongqh.tradeservice.messaging;

import com.dongqh.hmapi.dto.OrderCreatedMessage;
import org.springframework.amqp.AmqpException;
import org.springframework.amqp.core.ReturnedMessage;
import org.springframework.amqp.rabbit.connection.CorrelationData;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

@Component
public class OrderCreatedPublisher {
    private final RabbitTemplate rabbitTemplate;
    private final Duration confirmTimeout;

    public OrderCreatedPublisher(RabbitTemplate rabbitTemplate,
                                 @Value("${hm.messaging.publisher-confirm-timeout:5s}") Duration confirmTimeout) {
        this.rabbitTemplate = rabbitTemplate;
        this.confirmTimeout = confirmTimeout;
    }

    public void publish(OrderCreatedMessage event) {
        CorrelationData correlation = new CorrelationData(event.eventId().toString());
        rabbitTemplate.convertAndSend(OrderMessaging.EVENT_EXCHANGE,
                OrderMessaging.ORDER_CREATED_KEY, event, correlation);
        try {
            CorrelationData.Confirm confirm = correlation.getFuture()
                    .get(confirmTimeout.toMillis(), TimeUnit.MILLISECONDS);
            ReturnedMessage returned = correlation.getReturned();
            if (returned != null) {
                throw new AmqpException("RabbitMQ returned unroutable order-created event " + event.eventId());
            }
            if (!confirm.ack()) {
                throw new AmqpException("RabbitMQ NACK for order-created event " + event.eventId()
                        + ": " + confirm.reason());
            }
        } catch (TimeoutException exception) {
            throw new AmqpException("RabbitMQ confirm timed out for order-created event " + event.eventId(), exception);
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            throw new AmqpException("Interrupted while waiting for RabbitMQ confirm", exception);
        } catch (ExecutionException exception) {
            throw new AmqpException("RabbitMQ confirm failed for order-created event " + event.eventId(), exception);
        }
    }
}

package com.dongqh.tradeservice.messaging;

public final class OrderMessaging {
    public static final String EVENT_EXCHANGE = "trade.events.topic";
    public static final String DEAD_LETTER_EXCHANGE = "trade.events.dlx";
    public static final String ORDER_CREATED_KEY = "trade.order.created";
    public static final String CART_QUEUE = "cart.trade.order-created.queue";
    public static final String CART_DEAD_LETTER_QUEUE = "cart.trade.order-created.dlq";

    private OrderMessaging() {
    }
}

