        when(mapper.selectByIdForUpdate(101L)).thenReturn(order(2).setPayTime(paidAt));

        service.markOrderPaySuccess(101L, 7L, 8500, paidAt.plusSeconds(1));

        verify(mapper, never()).updateById(any(Order.class));
    }

